-- RocketMount | Locales/ptBR_Tips.lua
-- GERADO por tools/gerar_dicas.py em 2026-10-12 a partir de tools/dicas/*.json -- não edite à mão.
--
-- O português das dicas de jogadores (Data/MountTips.lua), por id de montaria. Fica num
-- arquivo à parte do ptBR.lua porque é gerado, e porque a chave aqui é o id: a frase em
-- inglês como chave dobraria o tamanho de cada dica.
local ADDON, ns = ...

if GetLocale() ~= "ptBR" then return end

ns.MountTipsLocal = {
    [264] = -- Blue Proto-Drake
        "Skadi só desce depois que o draco dele, {npc:26893|Grauf}, é derrubado: durante o evento, recolha três arpões ({item:37372|Arpão}) e dispare-os dos Lançadores de Arpões quando Grauf passar na frente deles. Depois de três acertos, Skadi pousa e a luta começa. O modo Heroico trava uma vez por dia por personagem, por isso os jogadores o fazem todo dia com vários personagens.",
    [265] = -- Time-Lost Proto-Drake
        "Ele divide os pontos de surgimento, as rotas de voo e o tempo de reaparecimento com {npc:32630|Viragosa}, um raro bem mais comum: só um dos dois fica no mundo por vez, e qualquer um deles pode ser o que aparece. Depois que um deles morre, o próximo leva horas para surgir (os jogadores relatam até cerca de 8 horas). Os dois surgem em quatro lugares e depois saem voando: perto de 31.5, 70.0, de 35.0, 76.5, de 51.1, 71.2 e de 52.3, 35.0.",
    [286] = -- Doomwalker's mounts
        "Só durante o evento de aniversário do WoW, em novembro. {npc:167749|Armagedom} é um chefe mundial: desde 2024 ele fica ao sul das Cavernas do Tempo, em {map:71|Tanaris}. É preciso grupo: entre na raide que se reúne ali ou em uma anunciada no localizador de grupos. O saque é uma vez por dia por personagem, então cada personagem alternativo tem a sua chance (2024 e 2025).",
    [287] = -- Doomwalker's mounts
        "Só durante o evento de aniversário do WoW, em novembro. {npc:167749|Armagedom} é um chefe mundial: desde 2024 ele fica ao sul das Cavernas do Tempo, em {map:71|Tanaris}. É preciso grupo: entre na raide que se reúne ali ou em uma anunciada no localizador de grupos. O saque é uma vez por dia por personagem, então cada personagem alternativo tem a sua chance (2024 e 2025).",
    [293] = -- Doomwalker's mounts
        "Só durante o evento de aniversário do WoW, em novembro. {npc:167749|Armagedom} é um chefe mundial: desde 2024 ele fica ao sul das Cavernas do Tempo, em {map:71|Tanaris}. É preciso grupo: entre na raide que se reúne ali ou em uma anunciada no localizador de grupos. O saque é uma vez por dia por personagem, então cada personagem alternativo tem a sua chance (2024 e 2025).",
    [312] = -- Sea Turtle
        "Só as áreas de pesca a dão, nunca a água aberta: as de {map:113|Nortúndria}, das zonas de Cataclysm e de {map:424|Pandária}, e os Destroços do Naufrágio em volta da {map:407|Ilha de Negraluna} durante a Feira de Negraluna. A chance por pescaria é mínima. Na sua guarnição de Draenor há outro caminho: uma {item:112633|Manjubinha Glacial} pescada ali e jogada no lago da guarnição invoca um Cavernícola ({npc:81171|Cavernícola Glacial} para a Horda, {npc:85715|Cavernícola Quedaluna} para a Aliança), que a deixa cair com cerca de 0,2% por morte. Cada membro de um grupo saqueia cada Cavernícola, por isso os jogadores os caçam em grupos de raide.",
    [393] = -- Phosphorescent Stone Drake
        "{npc:50062|Aeonaxx} surge amistoso, voando em círculos fechados bem alto em volta do Templo da Terra, mais ou menos na altura da entrada de Litocerne. Clique nele para montá-lo: ele fica hostil e a luta é feita de cima dele, e é preciso matar os dragonetes que ele invoca, ou eles sobrepujam você. {npc:3868|Busca-sangue}, um morcego, divide o surgimento com ele e pode aparecer no lugar dele.",
    [400] = -- Grey Riding Camel
        "O caminho até {npc:50245|Dormus} é uma {npc:50409|Estátua de Camelo Misteriosa} em {map:249|Uldum}. As estátuas aparecem só na versão de Cataclysm de Uldum ({npc:162419|Zidormi} faz a troca), em muitos lugares da zona, e a maioria só se desfaz em pó; a verdadeira leva você aos Lagos Vaporíferos, em {map:69|Feralas}, onde Dormus espera. Elas não podem ser selecionadas como alvo, mas a opção Placas de identificação de PNJs aliados as mostra de longe. Depois que uma estátua é clicada, a próxima aparece de 2 a 8 horas depois, e o Modo de Guerra ativado e o desativado têm cada um a sua.",
    [401] = -- Dark Phoenix
        "Vendida pelos vendedores de guilda a personagem Exaltado com uma guilda que tenha {achievement:4988|Glória da Guilda do Aventureiro do Cataclismo}. Entrar numa guilda que já a tem serve, mas a reputação com guilda nova começa do zero. Depois de aprendida, a montaria é sua em qualquer guilda.",
    [419] = -- Amani Battle Bear
        "É a recompensa de um evento com tempo em {map:333|Zul'Aman}: lá dentro, pegue {quest:29217|Os batedores capturados} junto ao portão fechado e abra o portão com o gongo. Um cronômetro começa: derrote {npc:23574|Akil'zon}, {npc:23576|Nalorakk}, {npc:23578|Jan'alai} e {npc:23577|Halazzi} e liberte o prisioneiro de cada um antes que o tempo acabe. A montaria fica na sacola do último prisioneiro libertado, então deixe Halazzi por último: a prisioneira dele, {npc:52945|Kasha}, revela então a Sacola da Kasha.",
    [420] = -- Subdued Seahorse
        "Os guias antigos que dizem que {npc:50005|Poseidus} aparece uma ou duas vezes por semana estão desatualizados: o tempo dele foi reduzido, e agora ele volta algumas horas depois de cada morte, em um dos seus lugares na {map:205|Vastidão Cintilante} ou nas {map:204|Profundezas Abissais}. Um personagem de Teste de Classe não recebe as rédeas dele.",
    [439] = -- Tyrael's Charger
        "Os {npc:205490|Goblins do Tesouro} só a deixaram cair no evento Um Emissário Ganancioso de 2023; na edição de 2025, não. Ela volta de tempos em tempos ao Posto Comercial, por 900 {currency:2032|Créditos do Comerciante} (julho de 2023 e setembro de 2026).",
    [445] = -- Experiment 12-B
        "A montaria não cai do próprio {npc:55294|Ultraxion}: ela está no Baú dos Aspectos Inferior que aparece depois da luta. Ela também pode vir na {item:208095|Arca de Tesouros Transtemporais} dada pela missão semanal da raide de Caminhada Temporal de Cataclysm, com cerca de 0,5% por arca.",
    [473] = -- Heavenly Onyx Cloud Serpent
        "O {npc:60491|Sha da Raiva} volta rápido, sempre no mesmo lugar, mas cada personagem só pode saqueá-lo uma vez por semana, por isso os jogadores o matam com vários personagens. Depois da morte, também dá para usar o Saque de bônus com um {currency:697|Antigo Amuleto de Boa Sorte}, vendido pelo {npc:64607|Comandante Lo Ping} nas {map:388|Estepes de Taolong} por 20 {currency:738|Amuleto Menor de Boa Sorte}, que caem das criaturas da {map:554|Ilha Perene}.",
    [515] = -- Son of Galleon
        "{npc:62346|Gailleon} volta rápido, sempre no mesmo lugar, mas cada personagem só pode saqueá-lo uma vez por semana, por isso os jogadores o matam com vários personagens. Depois da morte, também dá para usar o Saque de bônus com um {currency:697|Antigo Amuleto de Boa Sorte}, vendido pelo {npc:64607|Comandante Lo Ping} nas {map:388|Estepes de Taolong} por 20 {currency:738|Amuleto Menor de Boa Sorte}, que caem das criaturas da {map:554|Ilha Perene}.",
    [533] = -- Cobalt Primordial Direhorn
        "{npc:69161|Oondasta} volta rápido, sempre no mesmo lugar, mas cada personagem só pode saqueá-lo uma vez por semana, por isso os jogadores o matam com vários personagens. Caçadores podem domá-lo, e então ele some até o próximo surgimento. Depois da morte, também dá para usar o Saque de bônus com uma {currency:752|Runa Mogu do Destino}, vendida pela {npc:73305|Tecelã da Névoa Ai} na {map:554|Ilha Perene} por 1.000 {currency:777|Moeda Perene}.",
    [534] = -- Primordial Direhorns of the Zandalari Warbringer
        "O {npc:69769|Armipotente Zandalari} surge em cinco lugares de Pandária, cada um com seu próprio tempo, montado num escornante de uma cor, e só a montaria dessa cor pode cair dele. Não há bloqueio: cada morte é uma nova chance, por isso os jogadores voam de um lugar para o outro. Na {map:418|Selva de Krasarang} só aparece o de ardósia.",
    [535] = -- Primordial Direhorns of the Zandalari Warbringer
        "O {npc:69769|Armipotente Zandalari} surge em cinco lugares de Pandária, cada um com seu próprio tempo, montado num escornante de uma cor, e só a montaria dessa cor pode cair dele. Não há bloqueio: cada morte é uma nova chance, por isso os jogadores voam de um lugar para o outro. Na {map:418|Selva de Krasarang} só aparece o de ardósia.",
    [536] = -- Primordial Direhorns of the Zandalari Warbringer
        "O {npc:69769|Armipotente Zandalari} surge em cinco lugares de Pandária, cada um com seu próprio tempo, montado num escornante de uma cor, e só a montaria dessa cor pode cair dele. Não há bloqueio: cada morte é uma nova chance, por isso os jogadores voam de um lugar para o outro. Na {map:418|Selva de Krasarang} só aparece o de ardósia.",
    [542] = -- Thundering Cobalt Cloud Serpent
        "{npc:69099|Nalak} volta rápido, no céu em frente ao Trono do Trovão, mas cada personagem só pode saqueá-lo uma vez por semana, por isso os jogadores o matam com vários personagens. Depois da morte, também dá para usar o Saque de bônus com uma {currency:752|Runa Mogu do Destino}, vendida pela {npc:73305|Tecelã da Névoa Ai} na {map:554|Ilha Perene} por 1.000 {currency:777|Moeda Perene}.",
    [561] = -- Thundering Onyx Cloud Serpent
        "Não há bloqueio: as rédeas podem cair em toda morte de {npc:73167|Huolon}, várias vezes por dia. Quando ele aparece, não pode ser atacado por 1 minuto; espere isso acabar antes de atacá-lo.",
    [611] = -- Rattling Iron Cage (Tundra Icehoof, Armored Razorback, Warsong Direfang)
        "Ela vem numa {item:128025|Jaula de Ferro Chacoalhante}, que qualquer um dos quatro grandes raros da {map:534|Selva de Tanaan} pode deixar cair. A jaula entrega uma das suas três montarias ao acaso, e uma montaria que você já tem pode vir de novo. Cada raro dá saque uma vez por dia a cada personagem. Quando um raro aparece, o grito dele surge no chat da zona inteira: é a hora de voar até ele.",
    [612] = -- Bloodhoof Bull
        "O raro entrega a montaria a todos que o marcam. Um jogador relatou em 2026 que ele só apareceu depois de concluir a missão {quest:35169|... e justiça para Thrall}, de {map:550|Nagrand}: se você nunca o vê, avance antes a história da zona.",
    [622] = -- Rattling Iron Cage (Tundra Icehoof, Armored Razorback, Warsong Direfang)
        "Ela vem numa {item:128025|Jaula de Ferro Chacoalhante}, que qualquer um dos quatro grandes raros da {map:534|Selva de Tanaan} pode deixar cair. A jaula entrega uma das suas três montarias ao acaso, e uma montaria que você já tem pode vir de novo. Cada raro dá saque uma vez por dia a cada personagem. Quando um raro aparece, o grito dele surge no chat da zona inteira: é a hora de voar até ele.",
    [634] = -- Solar Spirehawk
        "{npc:83746|Rukhmar} é um chefe mundial que volta cerca de 15 minutos depois de cada morte, mas cada personagem só pode saqueá-lo uma vez por semana, então os jogadores o enfrentam com muitos personagens. Ele aparece junto de Beira-céu, por volta de 37, 39 em {map:542|Agulhas de Arak}, e voa pela zona até alguém puxá-lo. A montaria também aparece de vez em quando na Casa de Leilões do Mercado Negro.",
    [643] = -- Rattling Iron Cage (Tundra Icehoof, Armored Razorback, Warsong Direfang)
        "Ela vem numa {item:128025|Jaula de Ferro Chacoalhante}, que qualquer um dos quatro grandes raros da {map:534|Selva de Tanaan} pode deixar cair. A jaula entrega uma das suas três montarias ao acaso, e uma montaria que você já tem pode vir de novo. Cada raro dá saque uma vez por dia a cada personagem. Quando um raro aparece, o grito dele surge no chat da zona inteira: é a hora de voar até ele.",
    [655] = -- Sunhide Gronnling
        "O raro entrega a montaria a todos que o marcam, e leva muitas horas para voltar, então os jogadores o esperam juntos, em grupos anunciados em Grupos prontos. A antiga regra de que ele leva ao menos 48 horas não vale mais, segundo um relato de 2026.",
    [657] = -- Garn Nighthowl
        "Só um exemplar cai por morte, para um único jogador do grupo. O item não é vinculado, então também pode ser comprado na Casa de Leilões. {npc:81001|Nok-Karosh} volta em menos de uma hora depois de cada morte.",
    [682] = -- Voidtalon of the Dark Star
        "A montaria está num ovo do outro lado do Gume da Realidade, um portal, e o ovo sempre a entrega. O portal aparece raramente, em um dos lugares marcados de seis zonas de Draenor, fica alguns minutos e leva só o primeiro jogador que clicar nele. Cada zona conta o tempo por conta própria: os jogadores deixam um personagem em cada zona e percorrem os lugares.",
    [802] = -- Long-Forgotten Hippogryph
        "Cinco Cristais Efêmeros aparecem ao mesmo tempo em pontos sorteados de {map:630|Azsuna}, muitos dentro de cavernas. Tocar o primeiro dá 8 horas para tocar os outros quatro; morrer zera a contagem. Outros jogadores estão atrás dos mesmos cristais, e quando alguém termina todos somem até a rodada seguinte.",
    [803] = -- Covenant mounts of the rares of Korthia
        "Cada personagem tem uma tentativa por dia em cada raro de {map:1961|Korthia}. O que o raro deixa cair não é a montaria, mas o que leva a ela. Jogadores com renome baixo as conseguiram.",
    [838] = -- Fathom Dweller
        "Comece com {npc:102695|Drak'thul}, em 37.2, 71.7 na {map:646|Costa Partida}: converse com ele até ele mandar você embora. Pegue a {item:139783|Relíquia Envelhecida} num monte de terra no fundo da caverna em 58.5, 54 (se pedras bloquearem a passagem, saia e entre de novo no jogo), traga-a de volta e converse com ele outra vez, várias vezes, até ele não ter mais nada a dizer. Depois, clique nos dez Orbes Famintos escondidos em cavernas das Ilhas Partidas, exatamente na ordem; o décimo está na mesa dele. A lista de lugares é longa: está nos guias da página da montaria no Wowhead. Feito isso, a missão mundial de {npc:111573|Kosumoth, o Faminto} aparece em {map:790|Olho de Azshara} (a zona aberta, não a masmorra); a recompensa às vezes é a montaria e às vezes o mascote {item:140261|Garra Voraz}.",
    [928] = -- Dune Scavenger
        "Qualquer criatura de {map:864|Vol'dun} pode deixá-la cair, com chance muito pequena por morte: os raros marcados no mapa são só algumas delas. Ela não fica vinculada ao ser recolhida, então também pode ser comprada na Casa de Leilões.",
    [931] = -- Netherlord's Accursed Wrathsteed
        "Só um bruxo que já concluiu a missão da montaria de classe, {quest:46243|Corcel Iracundo de Zoroth}, a recebe: antes disso, o raro não a deixa cair, e matá-lo de novo no mesmo dia não adianta, porque ele dá saque uma vez por dia. Com a missão concluída, os jogadores relatam recebê-la na primeira morte. {npc:119629|Lorde Hel'nurath} aparece sem hora certa e fica por um tempo. Só bruxos podem montá-la.",
    [947] = -- Riddler's Mind-Worm
        "Leia oito páginas nesta ordem; cada uma libera a seguinte. 1: estante do térreo do Saguão da Destreza, em {map:627|Dalaran}. 2: mesa junto ao poço lunar, {map:47|Floresta do Crepúsculo} 49.1, 33.9. 3: raide Terras do Fogo, no fundo à esquerda da plataforma de {npc:52409|Ragnaros}. 4: {map:249|Uldum} 70.5, 78.0; antes, fale com {npc:162419|Zidormi} em Ramkahen para ver a Uldum antiga, senão a página não está lá. 5: raide Cerco a Orgrimmar, canto sudoeste da sala do {npc:71734|Sha do Orgulho}. 6: masmorra Nascente da Eternidade, na escadaria perto de 75.4, 65.4 do mapa dela. 7: {map:379|Monte Kun-Lai} 34.6, 50.9, entre as patas da estátua do tigre. 8: Uldum 76.4, 53.6, na base da estátua. Então abra o baú no marcador em {map:52|Cerro Oeste}. As páginas já lidas ficam guardadas de uma semana para outra.",
    [955] = -- Argus rares (Vile Fiend, Maddened Chaosrunner, Lambent Mana Ray, Crimson Slavermaw, Acid Belcher, Biletooth Gnasher)
        "Cada um destes raros de Argus dá saque uma vez por dia a cada personagem, e eles não estão todos presentes todos os dias: revezam-se. O dia em que a missão mundial do raro está ativa é o dia de caçá-lo, e os jogadores então o matam com vários personagens.",
    [956] = -- Leaping Veinseeker
        "Qualquer criatura de {map:863|Nazmir} pode deixá-la cair, com chance muito pequena por morte: o raro marcado no mapa é só uma delas. Os jogadores caçam os trolls do Descanso de Torga, perto de 59, 22. Ela não fica vinculada ao ser recolhida, então também pode ser comprada na Casa de Leilões.",
    [961] = -- Lucid Nightmare
        "Começa em {map:627|Dalaran}, com um bilhete no andar de cima da loja em 50, 56. Depois, na ordem: em Ulduar, depois do {npc:33293|Desconstrutor XT-002}, uma alavanca no canto noroeste da sala e um piso de luzes para desenhar uma engrenagem; em Ahn'Qiraj, ao lado da sala de {npc:15727|C'Thun}, um minijogo de combinar peças; em {map:207|Geodomo}, uma fenda na caverna Abismos Esfacelados (63.8, 22.5) e, lá embaixo, uma cadeira para examinar usando uma {item:10025|Máscara de Umbratrama} (compre antes); em Gnomeregan, dez consoles ajustados em 1222176597; {map:641|Val'sharah} 66, 36.5, um minijogo de desembaraçar fios; {map:379|Monte Kun-Lai} 53.4, 49, o labirinto, a parte mais difícil: leve o orbe de cada cor à runa da mesma cor, cinco vezes. A recompensa está na cripta atrás de Karazhan. Cada bilhete leva ao seguinte; o guia completo é longo.",
    [970] = -- Argus rares (Vile Fiend, Maddened Chaosrunner, Lambent Mana Ray, Crimson Slavermaw, Acid Belcher, Biletooth Gnasher)
        "Cada um destes raros de Argus dá saque uma vez por dia a cada personagem, e eles não estão todos presentes todos os dias: revezam-se. O dia em que a missão mundial do raro está ativa é o dia de caçá-lo, e os jogadores então o matam com vários personagens.",
    [973] = -- Argus rares (Vile Fiend, Maddened Chaosrunner, Lambent Mana Ray, Crimson Slavermaw, Acid Belcher, Biletooth Gnasher)
        "Cada um destes raros de Argus dá saque uma vez por dia a cada personagem, e eles não estão todos presentes todos os dias: revezam-se. O dia em que a missão mundial do raro está ativa é o dia de caçá-lo, e os jogadores então o matam com vários personagens.",
    [979] = -- Argus rares (Vile Fiend, Maddened Chaosrunner, Lambent Mana Ray, Crimson Slavermaw, Acid Belcher, Biletooth Gnasher)
        "Cada um destes raros de Argus dá saque uma vez por dia a cada personagem, e eles não estão todos presentes todos os dias: revezam-se. O dia em que a missão mundial do raro está ativa é o dia de caçá-lo, e os jogadores então o matam com vários personagens.",
    [980] = -- Argus rares (Vile Fiend, Maddened Chaosrunner, Lambent Mana Ray, Crimson Slavermaw, Acid Belcher, Biletooth Gnasher)
        "Cada um destes raros de Argus dá saque uma vez por dia a cada personagem, e eles não estão todos presentes todos os dias: revezam-se. O dia em que a missão mundial do raro está ativa é o dia de caçá-lo, e os jogadores então o matam com vários personagens.",
    [981] = -- Argus rares (Vile Fiend, Maddened Chaosrunner, Lambent Mana Ray, Crimson Slavermaw, Acid Belcher, Biletooth Gnasher)
        "Cada um destes raros de Argus dá saque uma vez por dia a cada personagem, e eles não estão todos presentes todos os dias: revezam-se. O dia em que a missão mundial do raro está ativa é o dia de caçá-lo, e os jogadores então o matam com vários personagens.",
    [1019] = -- Goldenmane
        "Qualquer criatura do {map:942|Vale Trovamare} pode deixá-la cair, com chance muito pequena por morte: os raros marcados no mapa são só algumas delas. Os jogadores caçam na Manufatura Salobra, na ponta nordeste da Praia do Marujo, onde as criaturas voltam depressa. Ela não fica vinculada ao ser recolhida, então também pode ser comprada na Casa de Leilões.",
    [1057] = -- Nazjatar Blood Serpent
        "1. Junte 20 de {item:161344|Fragmento Abissal}: cai de criaturas de Kul Tiraz e Zandalar e pode ser comprado na casa de leilões.\n2. Em {map:942|Vale Trovamare}, em 73.5, 23.6, há uma caverna atrás de uma cachoeira com um altar no fundo: junte ali os fragmentos na {item:161345|Essência do Abismo Abominável}.\n3. Entre na mina em 46.5, 36.1 e desça até a pequena estátua em 59.4, 54.2 no mapa da mina. Use a essência ali: o {npc:140474|Seguidor do Abismo} vem.\n4. Só quem invocou tem chance da montaria. Em 2023 um personagem de nível 70 o matou sozinho.",
    [1173] = -- Arathi Highlands Warfront rares
        "Estes raros ficam no Planalto Arathi do Front de Guerra. Cada personagem pode saquear cada um deles uma vez por ciclo do Front de Guerra, isto é, até o controle da zona passar para a outra facção: matar de novo antes disso não dá nada. O {item:158075|Coração de Azeroth} não é necessário: sem ele você pode não receber Azerita, mas a montaria ainda pode cair.",
    [1174] = -- Arathi Highlands Warfront rares
        "Estes raros ficam no Planalto Arathi do Front de Guerra. Cada personagem pode saquear cada um deles uma vez por ciclo do Front de Guerra, isto é, até o controle da zona passar para a outra facção: matar de novo antes disso não dá nada. O {item:158075|Coração de Azeroth} não é necessário: sem ele você pode não receber Azerita, mas a montaria ainda pode cair.",
    [1180] = -- Arathi Highlands Warfront rares
        "Estes raros ficam no Planalto Arathi do Front de Guerra. Cada personagem pode saquear cada um deles uma vez por ciclo do Front de Guerra, isto é, até o controle da zona passar para a outra facção: matar de novo antes disso não dá nada. O {item:158075|Coração de Azeroth} não é necessário: sem ele você pode não receber Azerita, mas a montaria ainda pode cair.",
    [1182] = -- Arathi Highlands Warfront rares
        "Estes raros ficam no Planalto Arathi do Front de Guerra. Cada personagem pode saquear cada um deles uma vez por ciclo do Front de Guerra, isto é, até o controle da zona passar para a outra facção: matar de novo antes disso não dá nada. O {item:158075|Coração de Azeroth} não é necessário: sem ele você pode não receber Azerita, mas a montaria ainda pode cair.",
    [1183] = -- Arathi Highlands Warfront rares
        "Estes raros ficam no Planalto Arathi do Front de Guerra. Cada personagem pode saquear cada um deles uma vez por ciclo do Front de Guerra, isto é, até o controle da zona passar para a outra facção: matar de novo antes disso não dá nada. O {item:158075|Coração de Azeroth} não é necessário: sem ele você pode não receber Azerita, mas a montaria ainda pode cair.",
    [1185] = -- Arathi Highlands Warfront rares
        "Estes raros ficam no Planalto Arathi do Front de Guerra. Cada personagem pode saquear cada um deles uma vez por ciclo do Front de Guerra, isto é, até o controle da zona passar para a outra facção: matar de novo antes disso não dá nada. O {item:158075|Coração de Azeroth} não é necessário: sem ele você pode não receber Azerita, mas a montaria ainda pode cair.",
    [1199] = -- Darkshore Warfront rares
        "Estes raros ficam na {map:62|Costa Negra} do Front de Guerra. Cada personagem pode saquear cada um deles uma vez por ciclo do Front de Guerra: matar de novo não dá nada até o controle da zona mudar. O raro do lado de uma facção só aparece enquanto essa facção controla a Costa Negra, e essa vez volta mais ou menos a cada duas semanas.",
    [1200] = -- Darkshore Warfront rares
        "Estes raros ficam na {map:62|Costa Negra} do Front de Guerra. Cada personagem pode saquear cada um deles uma vez por ciclo do Front de Guerra: matar de novo não dá nada até o controle da zona mudar. O raro do lado de uma facção só aparece enquanto essa facção controla a Costa Negra, e essa vez volta mais ou menos a cada duas semanas.",
    [1201] = -- Frightened Kodo
        "O {npc:148790|Kodo Assustado} é amistoso: clique nele e a montaria é sua, sem luta, para as duas facções e qualquer que seja o controle do Front de Guerra. Ele corre depressa em volta dos lugares marcados, e só por cerca de 2 minutos depois que uma cópia nova da {map:62|Costa Negra} abre: depois que o reino reinicia, ou quando você entra numa cópia em que não havia ninguém (a tela de carregamento demora mais). Os jogadores usam um personagem de Teste de Classe num reino de pouca população, com o Modo de Guerra ligado, deixado no lugar e conectado de novo a cada 15 a 30 minutos.",
    [1203] = -- Darkshore Warfront rares
        "Estes raros ficam na {map:62|Costa Negra} do Front de Guerra. Cada personagem pode saquear cada um deles uma vez por ciclo do Front de Guerra: matar de novo não dá nada até o controle da zona mudar. O raro do lado de uma facção só aparece enquanto essa facção controla a Costa Negra, e essa vez volta mais ou menos a cada duas semanas.",
    [1205] = -- Darkshore Warfront rares
        "Estes raros ficam na {map:62|Costa Negra} do Front de Guerra. Cada personagem pode saquear cada um deles uma vez por ciclo do Front de Guerra: matar de novo não dá nada até o controle da zona mudar. O raro do lado de uma facção só aparece enquanto essa facção controla a Costa Negra, e essa vez volta mais ou menos a cada duas semanas.",
    [1229] = -- Mechagon rares
        "Nenhuma missão da {map:1462|Ilha de Gnomecan} é necessária: personagens que só voaram ou se teleportaram até a ilha a conseguiram. Cada personagem pode saquear uma vez por dia, e o raro volta cerca de 15 a 35 minutos depois de morrer. Um personagem que atingiu o raro e saiu do jogo antes de saquear recebe o saque pelo correio.",
    [1248] = -- Mechagon rares
        "Nenhuma missão da {map:1462|Ilha de Gnomecan} é necessária: personagens que só voaram ou se teleportaram até a ilha a conseguiram. Cada personagem pode saquear uma vez por dia, e o raro volta cerca de 15 a 35 minutos depois de morrer. Um personagem que atingiu o raro e saiu do jogo antes de saquear recebe o saque pelo correio.",
    [1250] = -- Mollie
        "{npc:138794|Devoraduna Kraulok} é um chefe mundial de {map:864|Vol'dun} que só aparece enquanto a missão mundial dele está ativa: uma semana a cada seis, no rodízio dos chefes mundiais de Battle for Azeroth. Enquanto ela está ativa, ele volta cerca de um minuto depois de morrer, e os jogadores trazem um personagem depois do outro. O personagem não precisa ter as missões mundiais liberadas, nem ver a missão, para receber o saque.",
    [1257] = -- Silent Glider
        "{map:1355|Nazjatar} tem que estar liberada para o personagem, pela missão de introdução da zona. {npc:152290|Silente} leva pelo menos 2 horas para voltar depois de morrer, muitas vezes até cerca de 4, e aparece em um de vários lugares no alto dos corais da Floresta de Corais. Cada personagem pode saquear uma vez por dia.",
    [1258] = -- Fabious
        "Não o ataque (ele não pode ser ferido): tire uma foto com ele usando o brinquedo {item:122674|Câmera de S.E.L.F.I.E. 2.0}, e a montaria vem. Ele não aparece como estrela no mapa, move-se devagar em volta de um dos lugares marcados de {map:1355|Nazjatar} e fica só de 3 a 6 minutos, menos em alguns lugares. Passam-se horas entre uma aparição e outra: os relatos vão de 2 a 9 horas de espera, e ele só foi visto em cópias da zona abertas havia 2 horas ou mais. Pouse antes de usar a câmera, ou você cai. Se a montaria não vier, tire a foto de novo com ele inteiro no quadro.",
    [1297] = -- Clutch of Ha-Li
        "{npc:157153|Ha-Li} só está lá enquanto o ataque ao {map:1530|Vale das Flores Eternas} é {quest:57008|Ataque: os clãs em guerra}, o dos Mogu. Voa em círculos no alto, a leste das Ruínas de Guo-Lai. Cada personagem pode saquear uma vez por dia. Um personagem que não começou a história do patch 8.3 pode não ver o ataque: em 2022 um jogador passou a vê-lo só aceitando {quest:56374|Um problema titânico}.",
    [1298] = -- Hopecrusher Gargon
        "Só um personagem Venthyr pode saqueá-la: personagens de outros pactos podem ajudar a matar, mas não têm chance de ganhar a montaria. Depois de aprendida, qualquer pacto pode montá-la.",
    [1304] = -- Mawsworn Soulhunter
        "{npc:174861|Canaz-sombra Empanturrado} só vem com a sua caçada, nas Galerias Ferais de {map:1543|A Gorja}: quatro caçadas se revezam ali, então esta fica ativa por três dias e meio e some por dez e meio. Mate os 6 grupos de inimigos junto da caverna; o canaz então corre para dentro dela e pode ser atacado. Com cerca de metade da vida, ele desce para o andar de baixo: clique nas correntes para segui-lo sem dano de queda. Uma tentativa por personagem a cada vez que a caçada está ativa. O evento já quebrou mais de uma vez e voltava a funcionar em 04/2026; se ele travar no seu reino, procure um grupo em outro.",
    [1306] = -- Swift Gloomhoof
        "{npc:168135|Égua Noturna} só é vista com um {item:178675|Apanhador de Sonhos}, feito em três passos:\n1. Pegue a {item:181243|Teia-de-almas Estragada} junto a uma carroça quebrada, numa plataforma em 19.7, 63.5, a oeste de Tirna Scithe; chegue lá com um planador ou uma {item:174042|Pitada de Pó de Fada}.\n2. Desmontado, entregue-a com 10 de {item:173204|Seda Desluminada} à {npc:165704|Anciã Gwenna} em 50.4, 33.0; ela só está ali depois de {quest:57871|Pimenta no olho dos outros}.\n3. Leve a {item:181242|Teia-de-almas Restaurada} a {npc:160262|Ysera}, no Coração da Floresta; quem é de outro pacto fala com os guardas da porta, e ela sai.\nUse o Apanhador de Sonhos na Bacia do Altar do Sonho: o efeito dura 5 minutos e se renova usando-o de novo. Cada um no grupo precisa do seu.",
    [1307] = -- Sundancer
        "Antes de tudo, compre um {item:180445|Planador Navestruz} na Casa de Leilões: ele se gasta a cada tentativa, e nenhum outro planador serve. Clique no Memorial Ancestral em 60.0, 94.0 em {map:1533|Bastião} para ganhar a Bênção do Cavaleiro do Sol (30 minutos). {npc:170548|Dançarino do Sol} voa em ronda pela região: espere acima do caminho dele (a borda em 60.9, 81.4 serve), desça da montaria, use o planador e pouse nas costas dele. Aperte Confortar sem parar, até o botão sumir: ele então leva você ao memorial e o deixa ali. Fale com ele para começar a luta. A montaria só é garantida para quem montou nele, e só se ele morrer em até 5 minutos depois do voo de planador.",
    [1310] = -- Horrid Dredwing
        "Só um personagem Venthyr pode saqueá-la. Ela só desce quando o Condutor de Ânima de um Venthyr está canalizando para o Monte da Decrepitude: leve uma {item:176397|Seta da Cova Temível} do castelo a oeste, perto de 42.7, 73.4, a {npc:165327|Esmagasa} em 46.3, 77.8. Ele dispara a {npc:165324|Balista Deimedo} contra ela, e então ela pode ser atacada. Se Esmagasa ficar parado olhando a balista, o evento travou nessa cópia da zona: entrar no grupo de outro jogador costuma levar você a uma que funciona.",
    [1311] = -- Mounts of the Mogu assault in the Vale of Eternal Blossoms
        "Só enquanto o {map:1530|Vale das Flores Eternas} está sob o Ataque: Mogu, um dos ataques que se revezam ali a cada poucos dias; o mapa-múndi mostra o que está ativo. Se o Vale estiver como era antes da guerra, {npc:163463|Zidormi}, em 80.5, 32.0, leva você ao presente. Um jogador contou em 2022 que, para o Vale estar nessa fase, basta ter aceitado a missão {quest:56374|Um problema titânico}, da história de Battle for Azeroth.",
    [1313] = -- Rajani Warserpent
        "{npc:160711|Zhang Khu} a vende por 1 {item:174230|Escama de Serpente das Nuvens Imaculada}, e não pede reputação. A escama cai raramente de {npc:157162|Rei Lun}, um raro dentro dos Salões de Guo-Lai, no {map:1530|Vale das Flores Eternas}: da entrada em 22.2, 24.6, siga em frente e desça até o piso mais baixo. Ele só está lá enquanto o ataque ao Vale é {quest:57008|Ataque: os clãs em guerra}, o dos Mogu.",
    [1314] = -- Uldum assault rares
        "Estes raros ficam em {map:1527|Uldum}, a dos ataques de N'Zoth, do patch 8.3. Cada personagem pode saquear cada um deles uma vez por dia.",
    [1315] = -- Mail Muncher
        "Nas Visões Horrendas, clicar numa caixa de correio chama uma criatura e, de vez em quando, o {npc:160708|Papa-carta}, que sempre deixa cair a montaria. Não é preciso máscara, e a visão não precisa ser concluída. Os jogadores vão até a primeira caixa de correio, saem da visão se não for ele e entram de novo; os relatos vão de 26 a cerca de 60 entradas.",
    [1317] = -- Uldum assault rares
        "Estes raros ficam em {map:1527|Uldum}, a dos ataques de N'Zoth, do patch 8.3. Cada personagem pode saquear cada um deles uma vez por dia.",
    [1319] = -- Uldum assault rares
        "Estes raros ficam em {map:1527|Uldum}, a dos ataques de N'Zoth, do patch 8.3. Cada personagem pode saquear cada um deles uma vez por dia.",
    [1324] = -- Elusive Quickhoof
        "{npc:162681|Casco-veloz Esquivo} é uma alpaca amistosa que aparece em um dos lugares marcados de {map:864|Vol'dun}, fica cerca de 10 minutos e leva horas para voltar. Compre antes um {item:161128|Mix de Folhas Verdes Litorâneas} e dê a ela: a montaria é sua. Ela não tem marcador de raro no mapa; anda, e pode estar deitada. Vários jogadores podem alimentar a mesma, em grupo de raide também.",
    [1327] = -- Mounts of the Mogu assault in the Vale of Eternal Blossoms
        "Só enquanto o {map:1530|Vale das Flores Eternas} está sob o Ataque: Mogu, um dos ataques que se revezam ali a cada poucos dias; o mapa-múndi mostra o que está ativo. Se o Vale estiver como era antes da guerra, {npc:163463|Zidormi}, em 80.5, 32.0, leva você ao presente. Um jogador contou em 2022 que, para o Vale estar nessa fase, basta ter aceitado a missão {quest:56374|Um problema titânico}, da história de Battle for Azeroth.",
    [1328] = -- Mounts of the Mogu assault in the Vale of Eternal Blossoms
        "Só enquanto o {map:1530|Vale das Flores Eternas} está sob o Ataque: Mogu, um dos ataques que se revezam ali a cada poucos dias; o mapa-múndi mostra o que está ativo. Se o Vale estiver como era antes da guerra, {npc:163463|Zidormi}, em 80.5, 32.0, leva você ao presente. Um jogador contou em 2022 que, para o Vale estar nessa fase, basta ter aceitado a missão {quest:56374|Um problema titânico}, da história de Battle for Azeroth.",
    [1355] = -- Runestags of the Queen's Conservatory
        "Só para personagem dos Feérios Noturnos. Plante um espírito no Conservatório da Rainha com {item:176832|Farinha de Raiz de Semente Selvagem} nos canteiros ligados a ele e abra o tesouro quando ele crescer: ele pode trazer qualquer uma das duas.",
    [1358] = -- Runestags of the Queen's Conservatory
        "Só para personagem dos Feérios Noturnos. Plante um espírito no Conservatório da Rainha com {item:176832|Farinha de Raiz de Semente Selvagem} nos canteiros ligados a ele e abra o tesouro quando ele crescer: ele pode trazer qualquer uma das duas.",
    [1360] = -- Shimmermist Runner
        "Ela está no fim do labirinto do Enleio do Véu da Névoa, em {map:1565|Ardena}. O caminho está escrito no Conto do Emaranhado, um pergaminho numa árvore em 32.5, 53.1: a cada cruzamento, passe pelo portão de lâmpadas azuis. A partir da entrada em 31.0, 54.5 é esquerda, direita, esquerda, direita, em frente e esquerda. Com um portão errado, {npc:171767|Shizgher} não está lá no fim. Derrote-o em 26.4, 59.0 e clique no {npc:171699|Corredor Brumescente} que ele segura. Se ele não estiver, saia até a entrada e recomece. A {item:174042|Pitada de Pó de Fada}, saque comum de criaturas de Ardena, deixa você voar por 2 minutos por cima das criaturas do labirinto, pelos mesmos portões.",
    [1362] = -- Spinemaw Gladechewer
        "{npc:164107|Domagorm Tizo} é chamado lutando no Enleio do Véu da Névoa: mate o {npc:166736|Terror Pinhespinho}, o {npc:166735|Guardião Demente} que ele monta e os outros espriggans dali, até um deles gritar no bate-papo pedindo ajuda a Tizo. Então vem {npc:164110|Bocanha}; mate-o, e Tizo aparece ali mesmo. Quem participa da morte pode saquear. Pode levar minutos ou uma hora; em 09/2026 um jogador não conseguiu fazê-lo aparecer em mais de uma hora, então pode estar quebrado.",
    [1366] = -- Bonehoof Tauralus
        "Só personagem dos Necrolordes com {npc:162151|Nina} junto tem chance. Para tê-la: a Fábrica de Abominações no nível 2 e a sua sequência de missões; depois mate {npc:175510|Ceifalmas Anka} perto de 70, 41 em {map:1536|Maldraxxus}, abra a jaula com a {item:184354|Chave de Jaula de Ceifalmas} e faça {quest:59615|Todo cão tem seu dia}. Na fábrica, monte o corpo dela com 20 de {item:178061|Carne Maleável} na {npc:167042|Mesa de Suturar Abominável} e peça que ela venha com você. Bata em Tahonta você mesmo: um jogador ficou sem saque quando Nina o matou sozinha. Saquear você mesmo ou pela habilidade de Nina, os dois servem. Mesmo assim é rara: há jogadores com centenas de mortes.",
    [1370] = -- Armored Bonehoof Tauralus
        "Só personagem dos Necrolordes pode consegui-la. {npc:168147|Sabriel, a Cutilóssea} luta no meio do Teatro da Dor só enquanto o Condutor de Ânima de um Necrolorde está canalizando para lá, e os jogadores descobriram em 2021 que a montaria só cai para quem tem o condutor no nível 3 e canaliza para lá naquele dia. Com 0,5% de chance, comprá-la é mais rápido.",
    [1379] = -- Endmire Flyer
        "{npc:166521|Famu, o Infinito} fica escondido até alguém falar com {npc:166483|Perscrutadora Hilda}, ali perto no Charco Derradeiro: isso começa o evento, e depois de algumas ondas Famu vem. É difícil sozinho, mas Hilda continua lutando com ele se você morrer. Qualquer pacto pode saquear.",
    [1387] = -- Desire's Battle Gargon
        "Para personagem Venthyr, pela {map:1644|Corte das Brasas} de Pecádia, que acontece uma vez por semana. A convidada é a Condessa, liberada com a Corte das Brasas no nível 4 e a missão de convite dela, {quest:60948|RSVP: A Condessa}. Leve a amizade dela a Melhor Amigo: jogadores relatam a montaria no tributo dela na primeira Corte depois disso, com o humor dela no alto ao fim. Não é certo: um jogador, em 2025, fez 7 Cortes como Melhor Amigo sem ela.",
    [1389] = -- Battle Gargon Silessa
        "Para personagem Venthyr com a Rede de Espelhos no nível 3. Um Espelho Quebrado é consertado com um {item:181363|Kit de Reparo de Espelho Feito à Mão} e leva a uma sala com um baú, que pode ter a montaria; cada baú abre uma vez por dia. Há 3 espelhos de cada vez, sempre um de 4 grupos fixos de 3, de 12 lugares. O mapa marca os espelhos do grupo que está na vez, que o jogo informa; para personagem a quem os espelhos não servem, não marca nenhum. O grupo muda na virada da semana, e às vezes no meio dela.",
    [1391] = -- Loyal Gorger
        "1. Faça {quest:60480|Charco Derradeiro}, de {npc:168618|Tesle, o Caguete} (65.2, 63.4 em {map:1525|Revendreth}): quem pulou essa missão nunca viu o item do passo 2.\n2. Com uma {item:173939|Ânima Sedutora}, que cai das criaturas do Charco Derradeiro, acenda os braseiros em 38.8, 72.0 e mate o {npc:160821|Engolidor da Beira do Mundo} que vem. Ele pode deixar cair a {item:180583|Cria do Engolidor Impressionável}; sem ela, tente de novo no dia seguinte.\n3. A cria foge. Desça ao Charco Derradeiro a partir do Retiro Sombrio: ela aparece e oferece uma missão. Oferece uma por dia, e a do dia 7 entrega a montaria.",
    [1392] = -- Mounts shared by the four covenant features
        "Cada pacto tem o seu caminho, pelo recurso do seu santuário. Necrolordes: com os {faction:2462|Mestres-das-suturas} em Exaltado, compre de {npc:159238|Átticus} por 5.000 de {currency:1813|Ânima-reserva}. Feérios Noturnos: pode vir no tesouro do {map:1662|Conservatório da Rainha} quando o espírito Divino indicado abaixo é cultivado com 4 de {item:176832|Farinha de Raiz de Semente Selvagem}; o espírito Superior do mesmo tipo também a dá, mais raramente. Venthyr: pode vir no tributo do convidado da Corte das Brasas indicado abaixo.",
    [1393] = -- Wild Glimmerfur Prowler
        "{npc:168647|Valfir, o Implacável} fica imune até alguém usar uma Semente de Ânima Faiscante nele. Só um personagem dos Feérios Noturnos cujo Condutor de Ânima está canalizando para Tirna Scithe vê a semente, em 30.5, 55.6: pegue-a e use o botão que aparece, em Valfir. Outros podem ajudar a matar, mas só os Feérios Noturnos ganham a montaria; um Feérico Noturno de nível baixo, sem canalização própria, a conseguiu.",
    [1395] = -- Phalynx of Humility
        "Só para personagem dos Kyrianos. Com o Condutor de Ânima, no primeiro nível, canalizando para o Templo da Pureza, o baú aparece em 60.2, 78.2. Perto dali, num lugar que muda, há um sino: clique nele para começar a prova e atravesse o chão sem ser atingido pelos círculos que se movem; ser atingido manda você de volta ao começo. No fim, abra o baú. Se não enxergar os círculos, ative Texturas projetadas nas opções de Gráficos.",
    [1397] = -- Wildseed Cradle
        "Junte as cinco ferramentas de {npc:171360|Estrelinha} no Jardim da Noite, em {map:1565|Ardena}: {item:180758|Cesta do Jardineiro} junto à água em 40.3, 52.6, {item:180754|Martelo do Jardineiro} numa carroça em 39.8, 54.4, {item:180759|Diário da Noite} numa mesa no alto da plataforma da árvore em 39.0, 56.9 (chega-se pelas pontes entre as árvores), {item:180756|Flauta do Jardineiro} no chão em 38.5, 58.1 e {item:180757|Varinha do Jardineiro} debaixo de uma carroça em 38.8, 60.1. Use uma delas para montar o kit e leve a ela em Tirna Vaal, 63.8, 37.6: ela dá Visão Lunar por 10 minutos, que mostra o baú atrás dela. Cada jogador precisa juntar as próprias ferramentas.",
    [1404] = -- Silverwind Larion
        "Junte os 50 Estilhaços de Cristal de Ânima do {map:1533|Bastião}, que fazem a conquista {achievement:14339|Juntando os cacos}: 45 pela área, 2 n'A Chaga Necrótica e 3 nas Torres da Ascensão. Só aparecem a partir do nível 60, e muitos ficam em beiradas e colunas que pedem um planador ou um salto cuidadoso. Nas masmorras, pegue o seu antes de qualquer outro do grupo: jogadores que perderam a vez ficaram sem o estilhaço e tiveram de refazer a masmorra. Com os 50, {npc:171732|Forjalita Hefésios}, em 59.2, 31.4, forja a {item:180858|Marreta de Cristal dos Arautos}; toque com ela a Véspera do Vento Prateado em 36.0, 25.2 e abra a dádiva que aparece ao lado.",
    [1408] = -- Mounts shared by the four covenant features
        "Cada pacto tem o seu caminho, pelo recurso do seu santuário. Necrolordes: com os {faction:2462|Mestres-das-suturas} em Exaltado, compre de {npc:159238|Átticus} por 5.000 de {currency:1813|Ânima-reserva}. Feérios Noturnos: pode vir no tesouro do {map:1662|Conservatório da Rainha} quando o espírito Divino indicado abaixo é cultivado com 4 de {item:176832|Farinha de Raiz de Semente Selvagem}; o espírito Superior do mesmo tipo também a dá, mais raramente. Venthyr: pode vir no tributo do convidado da Corte das Brasas indicado abaixo.",
    [1410] = -- Hulking Deathroc
        "{npc:157309|Erro Violeta} é invocado no {npc:165146|Tanque de Monstruosidades Misturadas}, 58.2, 74.2 em {map:1536|Maldraxxus}. As gosmas em volta deixam cair substâncias que qualquer um pode pegar e jogar no tanque: Muco Mefítico (azul) dos gigantes ao sul, Óleo Viscoso (vermelho) das gosmas menores ao sul, Gosma Miscível (amarela) dos gigantes ao norte. Com 30, sai um raro, e qual depende da mistura: para este, tanto azul quanto vermelho e menos amarelo, como 15 azuis e 15 vermelhos. Se nada cair, faça antes {quest:59430|Que a peste assole sua casa} e {quest:58431|Tanque de poções}. Durante {quest:59234|Mistura monstruosa}, outros jogadores estragam a mistura. Pode ser invocado várias vezes; o saque vem uma vez por dia.",
    [1411] = -- Predatory Plagueroc
        "Só personagem dos Necrolordes pode consegui-la: os demais podem matar {npc:162741|Gieger}, mas a montaria nunca cai para eles. Também só um Necrolorde pode invocá-lo: puxe o {npc:162815|Último Fio}, em 31.5, 35.2 em {map:1536|Maldraxxus}, para junto do pé direito de Gieger. Depois que ele aparece, qualquer um pode ajudar a matar.",
    [1413] = -- Mounts shared by the four covenant features
        "Cada pacto tem o seu caminho, pelo recurso do seu santuário. Necrolordes: com os {faction:2462|Mestres-das-suturas} em Exaltado, compre de {npc:159238|Átticus} por 5.000 de {currency:1813|Ânima-reserva}. Feérios Noturnos: pode vir no tesouro do {map:1662|Conservatório da Rainha} quando o espírito Divino indicado abaixo é cultivado com 4 de {item:176832|Farinha de Raiz de Semente Selvagem}; o espírito Superior do mesmo tipo também a dá, mais raramente. Venthyr: pode vir no tributo do convidado da Corte das Brasas indicado abaixo.",
    [1414] = -- Sinrunner Blanchy
        "{npc:173468|Brancurinha Defunta} aparece em 63.1, 43.1 em {map:1525|Revendreth} a cada 1 a 2 horas e corre mais que uma montaria: fique no caminho e ela para por 5 minutos. Dê a ela uma coisa por dia, nesta ordem, por 6 dias, que não precisam ser seguidos: 8 {item:182581|Punhado de Aveia}, dos Sacos de Aveia nas fazendas do norte de {map:52|Cerro Oeste}; a {item:182585|Escova de Crina}, de {npc:173570|Risadinha} em 63.4, 61.8; 4 {item:182595|Ferradura Resistente}, nas estradas a leste e ao sul de Retiro Sombrio; o {item:182599|Balde de Água Limpa}: o balde vazio junto à escova, enchido na água de Ardena ou do Bastião; a {item:182597|Manta de Sela Confortável}, de {npc:171808|Ta'vera} em 51.1, 78.8 por 30 de uma carne que muda a cada semana; 3 {item:179271|Maçã da Cova Temível}, de {npc:167815|Mino} em 40.9, 46.7. Junte tudo antes.",
    [1415] = -- Arboreal Gulper
        "{npc:164112|Graw'uhdo} é invocado. Consiga um {item:175247|Cogumelo de Tamanho Descomunal}, que cai raramente de qualquer criatura de {map:1565|Ardena}: ele dura 20 minutos na bolsa. Leve-o à Greda Úmida em 32.5, 30.2 e clique na greda: um cogumelo cresce, e ele sai de dentro. Quem participa da morte pode saquear, então um cogumelo serve a um grupo inteiro.",
    [1426] = -- Ascended Skymane
        "Toque as cinco vésperas de {achievement:14734|Chamado dos Ascendidos} em até 5 minutos: 33.4, 59.8; 71.9, 38.9; 64.3, 69.8; 39.1, 20.4; 32.2, 17.8. Com a Pilotagem Aérea, um jogador faz isso sozinho. Um campeão aparece em cada sino, mas não pode ser atacado ali: cerca de um minuto depois do último sino os cinco se reúnem em 53.5, 88.4, no sul do {map:1533|Bastião}. Ataque-os para ter direito ao baú, que só personagem de nível 60 ou mais pode saquear. Sino tocado há pouco fica inativo; uma cópia nova da área, pelo Modo de Guerra, por exemplo, costuma estar com eles prontos. Qualquer pacto pode fazer.",
    [1434] = -- Deepstar Aurelid
        "{npc:180978|Hirukon} só vem para quem pesca com a {item:187923|Isca Aurelídea}, e dá a montaria a quem usou a isca; os outros têm uma chance baixa. A isca começa com a {item:187662|Gosma Estranha}, pescada no lago de Hirukon em 51.8, 74.3 de {map:1970|Zereth Mortis} (muito rara; é vendida na casa de leilões). Leve-a à {npc:182194|Baronesa Vashj} em 57.6, 92.0 de {map:1536|Maldraxxus}: ela pede o {item:187915|Baiacu Pungente}, pescado no Reservatório Presacurva em 52.2, 37.9 do {map:102|Pântano Zíngaro}; a {item:187922|Nadadeira}, pescada em 72.8, 24.3 de {map:1355|Nazjatar}, que escapa e se pega clicando nela; e o {item:187916|Cirro-mola}, na sacada de uma torre em 34.7, 75.0 da {map:205|Vastidão Cintilante}. Use a isca no lago, pesque no Aglomerado de Aurelídeos e Hirukon vem. Não mate Hirukon antes no mesmo dia: a montaria não cai numa segunda morte.",
    [1437] = -- Battle-Bound Warhound
        "Cai dos elites da arena do Teatro da Dor, a céu aberto em {map:1536|Maldraxxus}, e não da masmorra de mesmo nome. São lutas para grupo. Um personagem tem no máximo uma tentativa por dia em cada elite; os jogadores discordam sobre se só o primeiro elite do dia conta, então o seguro é matar cada um deles uma vez por dia.",
    [1449] = -- Covenant mounts of the rares of Korthia
        "Cada personagem tem uma tentativa por dia em cada raro de {map:1961|Korthia}. O que o raro deixa cair não é a montaria, mas o que leva a ela. Jogadores com renome baixo as conseguiram.",
    [1469] = -- Magmashell
        "1. Consiga uma {item:201883|Carapaça de Magma Vazia}: cai raramente das lesmas de lava do oeste de {map:2022|Costa Desperta}, entre elas {npc:193138|Sorvelava}.\n2. Leve-a à {npc:199010|Lesma Potencializada}, no fundo de uma poça de lava em 71.0, 25.0. Quando ela não está lá, volta em até 30 minutos.\n3. Clique na lesma, não na carapaça da bolsa, e aguente 20 segundos. A lava mata em menos que isso: leve um curador, um recurso da sua classe para não morrer, ou o brinquedo {item:200116|Chifre de Nado em Lava Eterno}.",
    [1475] = -- Hand of Bahmethra
        "Atormentadores da Thanator é um evento na própria {map:1543|Gorja}, não dentro da Thanator: a cada duas horas, tenentes aparecem num dos pontos marcados e, quando bastantes são mortos, vem um de cinco chefes ({npc:177330|Promathiz} e os outros). A montaria vem do {item:185972|Baú do Atormentador} que o chefe dá uma vez por semana por personagem (1,8% dos baús), ou do próprio chefe. Não é o evento Ira do Carcereiro, que também acontece na Gorja. Os jogadores contam cerca de 50 tentativas. O evento ficou quebrado de 09/2024 a 08/2025 e voltou a funcionar.",
    [1487] = -- Covenant mounts of the rares of Korthia
        "Cada personagem tem uma tentativa por dia em cada raro de {map:1961|Korthia}. O que o raro deixa cair não é a montaria, mas o que leva a ela. Jogadores com renome baixo as conseguiram.",
    [1493] = -- Covenant mounts of the rares of Korthia
        "Cada personagem tem uma tentativa por dia em cada raro de {map:1961|Korthia}. O que o raro deixa cair não é a montaria, mas o que leva a ela. Jogadores com renome baixo as conseguiram.",
    [1502] = -- Fallen Charger
        "Aparece n'{map:1543|A Gorja} com uma mensagem na área, galopa rumo a {map:1961|Korthia} e some quando chega lá: alcance-o no caminho. Seja qual for o ponto de partida, ele cruza uma das duas pontes vistas de 45.9, 61.9, nas Galerias Ferais: espere ali e olhe o minimapa. A espera pode ser de muitas horas. Num reino com poucos jogadores, A Gorja é desligada depois de ficar vazia por um tempo e recomeça quando alguém entra, e jogadores relatam a cavalgada 1 hora depois disso. Cada personagem pode saqueá-lo uma vez por dia.",
    [1503] = -- Hand of Nilganihmaht
        "A {npc:179572|Mão de Nilganihmaht} fica numa caverna em 25.5, 36.8 em {map:1543|A Gorja}, e só na fase da fenda da zona. Com os 5 anéis nela, ela oferece a missão da montaria:\n- {item:186608|Anel de Ouro de Nilganihmaht}: no topo de um pináculo em 19.2, 32.3, uma escalada.\n- {item:186607|Anel de Prata de Nilganihmaht}: no Baú da Dominação Lacrado em 66.0, 57.4, que pede 4 de {item:186727|Chave Quebra-selo}.\n- {item:186605|Anel Rúnico de Nilganihmaht}: de {npc:179735|Torglluun}, na fenda.\n- {item:186606|Anel-sinete de Nilganihmaht}: de {npc:170303|Exos, Arauto da Dominação}, que é invocado.\n- {item:186603|Anel de Pedra de Nilganihmaht}: feito de 4 pedaços achados na Fortaleza da Perdição, com {quest:63545|Montagem do plano}, do {quest:63543|Ataque dos Necrolordes}, disponível.",
    [1506] = -- Crimson Shardhide
        "Comece em {npc:179729|Zeladora Kah-Kay}, em 60.5, 23.2 em {map:1961|Korthia}, e siga as pegadas roxas que aparecem no chão até os restos em 44.4, 29.4: clicar neles traz {npc:179684|Malbog}, que um personagem bem equipado derrota sozinho. O evento não precisa estar ativo: fazer o mesmo caminho a partir dela faz os restos aparecerem do mesmo jeito, mas às vezes é preciso uma segunda volta. Cada personagem tem uma tentativa por dia.",
    [1507] = -- Darkmaul
        "{npc:180063|Malhonegro} é amistoso e fica em 42.8, 32.7 em {map:1961|Korthia}. Dê a ele um {item:187153|Gorjumelo Saboroso} e monte nele: a cavalgada conta assim que você sobe, sem precisar esperar os 2 minutos. Depois de 10 cavalgadas a montaria está na sua bolsa; com 10 cogumelos guardados, faz-se tudo de uma vez.\nO cogumelo vem, nem sempre, do Gorjumelo Invasivo, um tesouro que aparece em muitos lugares de Korthia. 5 deles podem ser abertos por dia.",
    [1509] = -- Garnet Razorwing
        "{npc:180160|Reliwik, o Desafiador} é um dos raros de {map:1961|Korthia} que só aparecem em alguns dias, num rodízio diário. Nos dias dele há um ninho em 56.2, 66.1 com três ovos, e clicar no que pode ser clicado o faz sair. Sem ninho ali, volte no dia seguinte; com só dois ovos, espere até 20 minutos pelo terceiro. No dia dele, ele volta a cada 10 a 20 minutos.",
    [1510] = -- Dusklight Razorwing
        "Leve 10 de {item:187054|Ovo de Talhasa Perdido} ao Ninho de Talhasa em 25.9, 51.4 em {map:1961|Korthia} e clique no ninho uma vez para cada ovo: no último a matriarca desce e entrega a montaria. Os ovos caem dos devoradores de Korthia, entre eles {npc:177245|Engolidor Voraz} e {npc:177582|Catador Ligeiro}, no máximo 2 por dia: são 5 dias. Podem ser entregues aos poucos.",
    [1514] = -- Rampaging Mauler
        "{npc:179472|Konthrogz, o Obliterador} não tem lugar próprio: quando um raro de {map:1961|Korthia} morre, de vez em quando se abre uma fenda onde ele caiu, anunciada na área. Saem levas de devoradores, e Konthrogz é o último; tem muita vida e é luta para grupo. Há dois tipos de fenda: o portal de Konthrogz é azul, e um cinza traz outra criatura. A fenda que sai de {npc:180160|Reliwik, o Desafiador} é sempre a de Konthrogz. Cada personagem tem uma tentativa por dia, e o mesmo raro pode ser morto de novo para tentar uma fenda.",
    [1545] = -- Divine Kiss of Ohn'ahra
        "{npc:190022|Godol} (56.4, 73.2 em {map:2023|Chapada Ohn'ahrana}) oferece {quest:72512|Uma brisa sussurrante} a quem tem renome 25 com {faction:2503|Centauro Maruuk}, com a última missão desse renome feita, terminou a cadeia de {item:192799|Rédeas de Lizi} e leva na bolsa, não no banco:\n- 3 de {item:201929|Fôlego Roubado de Ohn'ahra}: de {npc:186151|Balakar Khan}, o último chefe de A Ofensiva Nokhid, em qualquer dificuldade.\n- 1 {item:191507|Incenso Exultante} de qualidade 3: feito por alquimistas, vendido na casa de leilões.\n- 1 {item:201323|Essência do Despertar}: {npc:196707|Intendente Huseng} vende por 1 {item:194562|Areia Fortuita} e 50 de {currency:2003|Suprimentos das Ilhas do Dragão}; a areia cai de criaturas de {map:2025|Thaldraszus}, entre elas {npc:187475|Areia Eterna}. Não use a essência: ela é gasta.\nA missão termina com {npc:194796|Ohn'ahra}, em 57.6, 31.9.",
    [1553] = -- Liberated Slyvern
        "{npc:195353|Mascabrisa} sai da caverna em 29.8, 46.3 e voa em um grande círculo, bem alto, sobre a clareira: voe perto dele para puxá-lo. Ele volta cerca de 1 a 2 horas depois de morrer, e não há bloqueio: o mesmo personagem pode saqueá-lo toda vez que ele morre. O Descanso do Traidor costuma se dividir em fragmentos: se os jogadores ao seu redor sumirem, você foi levado para outro, onde o tempo é diferente.",
    [1584] = -- Colossal Plaguespew Mawrat
        "Cai de {npc:182120|Rhuv, Devorador da Ruína}, o dragão de {npc:182114|Iska, Pioneiro da Ruína}, e não de Iska. Iska é um dos três raros de {achievement:15392|Domínio da Duna} em {map:1970|Zereth Mortis}: um deles aparece de vez em quando com a atividade da área, sobretudo a morte dos raros dela, e a espera pode ser de muitas horas. Podem ser atacados cerca de 2 minutos depois de aparecer, e hoje Rhuv morre em um segundo: ataque no instante em que for possível. Em grupo, o ataque de um membro vale para todos. Saqueie na hora, antes de o corpo sumir. Rhuv e Iska têm bloqueios diários separados.",
    [1585] = -- Colossal Wraithbound Mawrat
        "Qualquer Baú de Suprimentos Górjuro de {map:1970|Zereth Mortis} pode tê-la, e não há limite por dia: abra todos os que encontrar. Eles ficam nos acampamentos górjuros. A pirâmide em 60.0, 32.0 tem três pontos próximos, em 59.4, 31.4, 60.1, 32.4 e 61.0, 30.6, e a Ilha dos Antecessores, no norte, tem quatro. Um baú volta entre 5 minutos e uma hora e meia depois. Quando outro jogador abre um, ele fica ali por um ou dois minutos, já fora do minimapa: confira com os próprios olhos.",
    [1617] = -- Verdant Skitterfly
        "Chegue a Renome 25 com {faction:2507|Expedição Dragoscama}. Daí em diante ela tem uma chance pequena de vir em cada Mochila do Batedor da Expedição.",
    [1619] = -- Ancient Salamanther
        "Qualquer um dos 16 raros do {map:2151|Recôndito Proibido} pode deixá-la cair, e um raro que você já matou hoje ainda pode deixá-la cair de novo. Compre a {item:204559|Essência de Adivinhação} por 2.000 {currency:2118|Transbordamento Elemental} com {npc:200564|Guardiã de Histórias Asketh}, na Aldeia Morqut: até a renovação diária, espíritos avisam cerca de 2 minutos antes de cada raro aparecer. Se ela cair, pode ser negociada com quem marcou o mesmo raro.",
    [1656] = -- Otto
        "1. Consiga uma {item:199340|Moeda de Ouro das Ilhas}: pescada nas Ilhas do Dragão, ou 75 {item:199338|Moeda de Cobre das Ilhas} trocadas com {npc:191608|O Grande Zapo}.\n2. Compre dele, com ela, o {item:202102|Saco de Tesouros do Zapo Imaculado}. Quase sempre ele traz os {item:202042|Óculos Aquáticos}; quando não traz, é outra moeda.\n3. Com os óculos, dance por 5 minutos na pista do bar debaixo d'água em {map:2022|Costa Desperta}, em 19.6, 36.5.\n4. Pegue o {item:202061|Barril de Peixe Vazio} e encha: 100 {item:202072|Peixe de Banquisa Frígido} (água aberta em volta de Iskaara), 25 {item:202073|Carpa Calamitosa} (lava em volta da Cidadela Obsidiana) e 1 {item:202074|Reibatana, o Sábio Peixe-de-bigode} (água em volta da Academia Algeth'ar).\n5. Leve o barril aonde você dançou: Otto oferece {quest:72738|O caminho para o coração de um Otto}. Aceite logo: ele vai embora e os peixes se perdem.",
    [1671] = -- Duskwing Ohuna
        "{item:207026|Coalescência do Surto Onírico} vem dos orbes verdes espalhados pela zona em que o Surto Onírico está ativo, e das criaturas mortas ali. {npc:210608|Celestine da Colheita} fica no símbolo do Surto Onírico no mapa.",
    [1672] = -- Zenet Hatchling
        "{npc:193209|Zenet Avis} voa em círculos, alto sobre um morro, por volta de 31.4, 63.8 em {map:2023|Chapada Ohn'ahrana}: voe perto dele e ele desce. Ele deixa cair o {item:200879|Ovo de Zenet}, que vira a montaria depois de 7 dias na bolsa. Depois de morto, leva horas para voltar. Os jogadores não esperam: entram em grupos da zona pelo Localizador de Grupos até cair onde ele está.",
    [1732] = -- Cobalt Shalewing
        "{npc:203625|Karokta} vive em uma parte da {map:2133|Caverna Zaralek} que se reveza com as outras: só aparece em alguns dias de um ciclo de 4 dias, e cada personagem o saqueia uma vez por ciclo. Ele volta de 45 minutos a 2 horas depois de morrer, e uma mensagem no bate-papo avisa logo antes de ele aparecer. A caverna troca você de fragmento sem aviso. Desde o fim de 2025 ele acompanha o seu nível como um elite mais forte: leve um grupo.",
    [1798] = -- Doomwalker's mounts
        "Só durante o evento de aniversário do WoW, em novembro. {npc:167749|Armagedom} é um chefe mundial: desde 2024 ele fica ao sul das Cavernas do Tempo, em {map:71|Tanaris}. É preciso grupo: entre na raide que se reúne ali ou em uma anunciada no localizador de grupos. O saque é uma vez por dia por personagem, então cada personagem alternativo tem a sua chance (2024 e 2025).",
    [1808] = -- Mounts of the Dreamseed Cache
        "Num lugar marcado no {map:2200|Sonho Esmeralda}, clique na terra para plantar uma semente. Minutos depois um baú abre para todos os que deram algo àquela planta.\n{currency:2650|Orvalho Esmeralda} não se planta: é dado a uma planta que já cresce, sua ou não, e enche a barra dela. A barra é de todos os que deram, e o que conta é chegar a 50 e a 100: no meio, nada muda.\nA {item:208047|Semente do Sonho Gigante} vem dos raros da zona e da melhor bolsa de {quest:78203|Superflorada}, de hora em hora.",
    [1810] = -- Mounts of the Dreamseed Cache
        "Num lugar marcado no {map:2200|Sonho Esmeralda}, clique na terra para plantar uma semente. Minutos depois um baú abre para todos os que deram algo àquela planta.\n{currency:2650|Orvalho Esmeralda} não se planta: é dado a uma planta que já cresce, sua ou não, e enche a barra dela. A barra é de todos os que deram, e o que conta é chegar a 50 e a 100: no meio, nada muda.\nA {item:208047|Semente do Sonho Gigante} vem dos raros da zona e da melhor bolsa de {quest:78203|Superflorada}, de hora em hora.",
    [1815] = -- Mounts of the Dreamseed Cache
        "Num lugar marcado no {map:2200|Sonho Esmeralda}, clique na terra para plantar uma semente. Minutos depois um baú abre para todos os que deram algo àquela planta.\n{currency:2650|Orvalho Esmeralda} não se planta: é dado a uma planta que já cresce, sua ou não, e enche a barra dela. A barra é de todos os que deram, e o que conta é chegar a 50 e a 100: no meio, nada muda.\nA {item:208047|Semente do Sonho Gigante} vem dos raros da zona e da melhor bolsa de {quest:78203|Superflorada}, de hora em hora.",
    [1816] = -- Mounts of the Dreamseed Cache
        "Num lugar marcado no {map:2200|Sonho Esmeralda}, clique na terra para plantar uma semente. Minutos depois um baú abre para todos os que deram algo àquela planta.\n{currency:2650|Orvalho Esmeralda} não se planta: é dado a uma planta que já cresce, sua ou não, e enche a barra dela. A barra é de todos os que deram, e o que conta é chegar a 50 e a 100: no meio, nada muda.\nA {item:208047|Semente do Sonho Gigante} vem dos raros da zona e da melhor bolsa de {quest:78203|Superflorada}, de hora em hora.",
    [1817] = -- Mounts of the Dreamseed Cache
        "Num lugar marcado no {map:2200|Sonho Esmeralda}, clique na terra para plantar uma semente. Minutos depois um baú abre para todos os que deram algo àquela planta.\n{currency:2650|Orvalho Esmeralda} não se planta: é dado a uma planta que já cresce, sua ou não, e enche a barra dela. A barra é de todos os que deram, e o que conta é chegar a 50 e a 100: no meio, nada muda.\nA {item:208047|Semente do Sonho Gigante} vem dos raros da zona e da melhor bolsa de {quest:78203|Superflorada}, de hora em hora.",
    [1833] = -- Mounts of the Dreamseed Cache
        "Num lugar marcado no {map:2200|Sonho Esmeralda}, clique na terra para plantar uma semente. Minutos depois um baú abre para todos os que deram algo àquela planta.\n{currency:2650|Orvalho Esmeralda} não se planta: é dado a uma planta que já cresce, sua ou não, e enche a barra dela. A barra é de todos os que deram, e o que conta é chegar a 50 e a 100: no meio, nada muda.\nA {item:208047|Semente do Sonho Gigante} vem dos raros da zona e da melhor bolsa de {quest:78203|Superflorada}, de hora em hora.",
    [1834] = -- Ochre Dreamtalon
        "A missão que a dá é a última de 5, e a cadeia leva 23 dias: uma planta cresce entre as missões. As esperas são de 5 dias, 5 dias, 3 dias para o fertilizante da terceira missão, 5 dias e 5 dias, cada uma contada de quando a missão anterior é entregue.\n1. Clique no broto em chamas em 48.7, 67.9 de {map:2200|Sonho Esmeralda}, A PÉ: montado, ele não responde. Clique duas vezes, para apagar o fogo e para limpá-lo, e ele dá {quest:77677|Um pouco d'água...}.\n2. As missões seguintes vêm de {npc:208337|Professor Borralho}, o instrutor de herborismo em 49.6, 62.8, ou da própria planta.\n3. Em {quest:77697|O nutriente certo...}, junte as três coisas clicando na {item:208644|Matéria Vegetal de Açoitadeira}: as bananas, clicadas, são comidas. Quando o fertilizante ficar pronto, saia do jogo e volte antes de usá-lo.\nUm jogador relata que o broto só respondeu depois do capítulo 5 da história da zona.",
    [1835] = -- Mounts of the Dreamseed Cache
        "Num lugar marcado no {map:2200|Sonho Esmeralda}, clique na terra para plantar uma semente. Minutos depois um baú abre para todos os que deram algo àquela planta.\n{currency:2650|Orvalho Esmeralda} não se planta: é dado a uma planta que já cresce, sua ou não, e enche a barra dela. A barra é de todos os que deram, e o que conta é chegar a 50 e a 100: no meio, nada muda.\nA {item:208047|Semente do Sonho Gigante} vem dos raros da zona e da melhor bolsa de {quest:78203|Superflorada}, de hora em hora.",
    [1943] = -- Incognitro, the Indecipherable Felcycle
        "Uma longa corrente secreta, ainda aberta depois do aniversário de 2024. 1. Conquiste {achievement:40870|O melhor detetive de Azeroth}: fora do evento, entregue os 11 caixotes da celebração para {npc:234262|Alyx} em {map:2339|Dornogal}. 2. O {npc:230042|Sobrevivente de Dalaran} em Dornogal (55.0, 29.0) leva você a uma caverna em Azj-Kahet e à {item:228938|Gema Peculiar}. O brinquedo {item:208092|Tocha de Pyrreth}, usado no toco do Refúgio do Marshal (44.5, 8.0, {map:78|Cratera Un'Goro}), dá a {item:228941|Chave Peculiar Inerte}: combine as duas. 3. Com a chave, use a tocha no lado leste de Karazhan (47.0, 69.0, {map:42|Trilha do Vento Morto}): dentro do portal, acenda oito pilares, cada um um enigma. 4. De volta àquela caverna, os {item:228966|Óculos de Visão de Estrelas} revelam uma plataforma: digite 84847078 no console dela para abrir este baú.",
    [1948] = -- Voidfire Deathcycle
        "Ela é reconstruída, não saqueada. Na {map:2404|Visão de Ventobravo}, com pelo menos 1 máscara ativa, há um piloto na mortecicleta no Distrito dos Anões, em 62.1, 31.2. Bata na mortecicleta até o piloto saltar, mate-o e então fale com ela. Faça devagar: quem a matou rápido demais não conseguiu falar com ela.\nDaí em diante ela fica estacionada em Dornogal, ao lado da entrada das visões. Ela pede seis tipos de peça: {item:240188|Motor Quatro em Linha Forjado no Caos}, {item:240190|Sistema de Escapamento de Mortecicleta}, {item:240182|Guidão Foice-Crânio}, {item:240185|Cristal de Caos Pulsante}, {item:240181|Selim de Mortecicleta de Couro de Javali} e 2 de {item:240179|Roda do Fogo do Caos}. Cada uma é montada com um pedaço achado nas visões, uns em Ventobravo e outros em Orgrimmar, e com materiais comprados ou fabricados. Instale todas e aperte o botão.",
    [1959] = -- Compass Rose
        "Só no evento do 10º aniversário de Hearthstone no WoW, de 11 a 22 de março de 2024. Um portal se abria a cada hora (a cada 30 minutos a partir de 15 de março) no Porto de Ventobravo, em Durotar do lado de fora de Orgrimmar e em {map:2112|Valdrakken}. Depois de 5 minutos, saíam lacaios de Hearthstone, e {npc:215146|Dr. Cabum}, que a deixa cair, vinha depois da morte de {npc:215147|Remendeiro} ou do {npc:215141|Yeti Ventogelante}. O mesmo personagem podia saqueá-lo várias vezes por dia.",
    [2038] = -- Clayscale Hornstrider
        "Vem da {quest:79226|Grande Escavação: Descanso do Traidor}, um evento do Arquivo Azerothiano na {map:2024|Vasta Lazúli} que começa a cada hora, no minuto 30. Depois de cerca de 9 minutos de escavação, {npc:208029|Sombra da Ruína} pousa: acerte-a para ter direito ao saque, porque a multidão a mata rápido. Ela e os tomos que o evento dá podem deixar cair a montaria, sem bloqueio: o mesmo personagem pode tentar a cada hora.",
    [2119] = -- Stonevault Mechsuit
        "{npc:219440|Grão-mensageiro Eirich}, na Abóboda de Pedra em Mítica, pode deixar cair {item:226683|Traje de Meca Defeituoso}, que começa uma cadeia com {npc:213875|Mensageiro Jurlax} (47.0, 32.4 em {map:2214|Fosso Ressonante}). Ele pede três berloques, um de cada vez: {item:219301|Lança-engrenangue Turbinado} de {npc:213216|Mensageira Dorlita} na Abóboda de Pedra, {item:219299|Fermentalizador Sinergético} de {npc:218523|Doura de Ricalhaz Nababa} na Hidromelaria Cinzagris e {item:219306|Buril do Rei da Vela} de {npc:208745|O Rei da Vela} na Fenda Chamanegra. A cadeia é da conta inteira, e o berloque só cai para classe que o usa (o de Doura é de Intelecto): outro personagem pode saqueá-lo. Qualquer nível de item serve.",
    [2144] = -- Delver's mounts sold by Reno Jackson (Dirigible, Gob-Trotter, Mana-Skimmer, OC91 Chariot)
        "Apesar do que diz o diário, desde Midnight {npc:226250|Reno Jackson}, em Dornogal, a vende por 10.000 de {currency:2815|Cristais de Ressonância}.",
    [2159] = -- Machine Defense Unit 1-11
        "O evento de {npc:227273|Maquinista Desperto} em {map:2214|Fosso Ressonante} tem 20 ondas, e a montaria só vem no Baú Desperto que aparece depois da última. Cerca de 6 baús em 100 a trazem; os relatos vão de 10 a mais de 70 tentativas. O baú vem uma vez por semana por personagem. As criaturas são de nível 80 para todos: um personagem de nível menor não tem luta mais fácil.",
    [2161] = -- Vivid Chloroceros, Elder Glowmite (Luminous Dust)
        "{currency:3385|Poeira Luminosa} vem das Mariposas Brilhantes espalhadas por {map:2413|Harandar}, 120 ao todo. Elas se abrem em três grupos de 40, nos Renomes 1, 5 e 6 com {faction:2704|Hara'ti}; o mapa só marca cada grupo depois, nos Renomes 2, 6 e 11. O jogador que as mapeou aconselha chegar ao Renome 9 antes de sair à procura.",
    [2165] = -- Soaring Meaderbee
        "{npc:226205|Cendvin} (74.4, 45.2 em {map:2248|Ilha de Dorn}) pede 900 de {item:225557|Pólen Borralheiro Fervilhante}. Ele cai das criaturas de elite a oeste da Hidromelaria Cinzagris: as abelhas e, na costa em volta de 73, 33, {npc:222797|Lobo da Tempestade} e {npc:222796|Ferrinuvem Nanico}. O pólen passa entre os personagens da conta. Os jogadores contam de 3 a 4 horas.",
    [2176] = -- Alunira
        "Alunira voa em volta do pico mais alto de {map:2248|Ilha de Dorn} (23.2, 58.5) atrás de um escudo. Qualquer criatura da ilha tem uma chance pequena de deixar cair {item:224025|Fragmento Estalante}; 10 deles formam um {item:224026|Receptáculo de Tempestade}, que quebra o escudo. Os raros menores, que voltam em minutos, deixam cair fragmentos com muito mais frequência do que as criaturas comuns, e os fragmentos passam entre os personagens da conta.\nEla dá saque uma vez por dia. Não a mate no grupo de outra pessoa no dia em que for usar o seu receptáculo: jogadores perderam o receptáculo assim.",
    [2178] = -- Nesting Swarmite
        "Nas Visões Horrendas, cada distrito tem uma pilha de lixo; clicar nela chama criaturas e, de vez em quando, o Enxamito Aninhado, que sempre deixa cair a montaria. Não é preciso máscara. Os jogadores conferem uma ou duas pilhas, saem da visão e entram de novo; os relatos vão da primeira pilha a mais de 70 tentativas.\n{map:2404|Visão de Ventobravo}: 55.8, 49.3 · 62.9, 30.7 · 73.6, 62.7 · 66.1, 76.3 · 52.6, 77.3.\n{map:2403|Visão de Orgrimmar}: 47.8, 75.0 · 40.7, 79.3 · 50.9, 45.2 · 69.0, 49.8 · 57.5, 60.6, esta dentro de uma loja e menor.",
    [2192] = -- Beledar's Spawn
        "{npc:207802|Cria de Beledar} aparece em {map:2215|Pouso Santo} quando Beledar escurece, a cada 3 horas, a primeira vez 1 hora depois da virada do dia, em um de vários pontos, e vai embora quando a escuridão acaba, 30 minutos depois. Personagem de nível 70 já pode saquear. Dá saque uma vez por dia por personagem, e cerca de 5,5% das mortes dão a montaria. Ela morre em segundos: os jogadores entram num grupo que tenha todos os pontos cobertos.",
    [2194] = -- Dauntless Imperial Lynx
        "Ela vem na {item:228741|Algibeira de Suprimentos dos Luminares}, entregue pelas fogueiras de {quest:76586|Semeando a Luz} em {map:2215|Pouso Santo}: as principais, e as missões paralelas que as fogueiras pequenas dão por 3 cristais. Cerca de 0,6% das algibeiras a trazem, e os relatos passam de 300. Personagem de nível 70 pode fazer.",
    [2205] = -- Ol' Mole Rufus
        "Cinco alavancas espalhadas por {map:2214|Fosso Ressonante} têm de ser puxadas ao mesmo tempo, por isso são precisos cinco jogadores. Uma mensagem no chat diz que deu certo, e algum tempo depois {npc:220285|Tocaieiro das Profundezas} aparece. Saque uma vez por dia por personagem, também abaixo do nível 80. O Wowhead conta a montaria em cerca de 6% das mortes; jogadores que contaram em raides dizem menos.",
    [2222] = -- Siesbarg
        "{npc:216046|Tka'ktath} (63, 66 em {map:2255|Azj-Kahet}, no alto de uma plataforma) deixa cair {item:225952|Ampola de Sangue de Tka'ktath} para personagem de nível 78 ou mais. Ele leva horas para voltar e é difícil sozinho; o saque é uma vez por dia. A ampola começa uma cadeia que pede, nesta ordem, 1.500 de {item:225950|Quitina Nerubiana}, 1.000 de {item:226135|Veneno Nerubiano} e 500 de {item:226136|Sangue Nerubiano}, todos de criaturas nerubianas, o sangue de poucas delas. A cadeia é do personagem. Os jogadores repetem as primeiras salas das masmorras Ara-Kara e Cidade das Tramas com seguidores, saindo e entrando de novo. As masmorras nerubianas antigas, como Azjol-Nerub, não contam. Para o sangue, um jogador conseguiu 270 em 40 minutos nos elites em volta de 65.0, 12.7.",
    [2225] = -- Timewalking vendor mounts
        "O vendedor só está lá enquanto a Caminhada Temporal da expansão dele está ativa. {currency:1166|Insígnia Transtemporal} pode ser passada entre os personagens da conta, na aba de moedas.",
    [2274] = -- Undermine cartel troves (Blackwater, Steamwheedle, Venture Co., Bilgewater)
        "A arca é o que o cartel entrega cada vez que a barra de reputação enche de novo depois de Exaltado. Muitos jogadores conseguiram a montaria na primeira arca, um precisou de 16.",
    [2276] = -- Ando the Gat's mounts (Darkfuse Chompactor, Flarendo the Furious, Thunderdrum Misfire)
        "{npc:235621|Ando, o Cato} fica DENTRO da raide Libertação da Inframina, subindo a escada depois da entrada. Os jogadores chegam a ele pelo Localizador de Raides, que {npc:231045|Teco Fineza} abre em 43.4, 51.5 de {map:2346|Inframina}.",
    [2278] = -- Ando the Gat's mounts (Darkfuse Chompactor, Flarendo the Furious, Thunderdrum Misfire)
        "{npc:235621|Ando, o Cato} fica DENTRO da raide Libertação da Inframina, subindo a escada depois da entrada. Os jogadores chegam a ele pelo Localizador de Raides, que {npc:231045|Teco Fineza} abre em 43.4, 51.5 de {map:2346|Inframina}.",
    [2279] = -- Ando the Gat's mounts (Darkfuse Chompactor, Flarendo the Furious, Thunderdrum Misfire)
        "{npc:235621|Ando, o Cato} fica DENTRO da raide Libertação da Inframina, subindo a escada depois da entrada. Os jogadores chegam a ele pelo Localizador de Raides, que {npc:231045|Teco Fineza} abre em 43.4, 51.5 de {map:2346|Inframina}.",
    [2281] = -- Undermine cartel troves (Blackwater, Steamwheedle, Venture Co., Bilgewater)
        "A arca é o que o cartel entrega cada vez que a barra de reputação enche de novo depois de Exaltado. Muitos jogadores conseguiram a montaria na primeira arca, um precisou de 16.",
    [2283] = -- Miscellaneous Mechanica mounts (Innovation Investigator, Asset Advocator, Margin Manipulator)
        "{item:234741|Mecanismos Diversos} cai, raramente, dos raros que cada cartel chama em {map:2346|Inframina}, e não só na primeira morte do dia; jogadores também o acharam nas caçambas transbordando. {npc:228286|Marquita Franjínea} fica em 43.3, 82.8. Os jogadores a consideram uma das coletas mais longas da expansão: um deles comprou a terceira montaria na casa de leilões. Um jogador achou 1 ou 2 em cada {item:232465|Arca de Sombrafuso} e conta cerca de 30 horas para os 25 de uma montaria.",
    [2289] = -- Undermine cartel troves (Blackwater, Steamwheedle, Venture Co., Bilgewater)
        "A arca é o que o cartel entrega cada vez que a barra de reputação enche de novo depois de Exaltado. Muitos jogadores conseguiram a montaria na primeira arca, um precisou de 16.",
    [2290] = -- Miscellaneous Mechanica mounts (Innovation Investigator, Asset Advocator, Margin Manipulator)
        "{item:234741|Mecanismos Diversos} cai, raramente, dos raros que cada cartel chama em {map:2346|Inframina}, e não só na primeira morte do dia; jogadores também o acharam nas caçambas transbordando. {npc:228286|Marquita Franjínea} fica em 43.3, 82.8. Os jogadores a consideram uma das coletas mais longas da expansão: um deles comprou a terceira montaria na casa de leilões. Um jogador achou 1 ou 2 em cada {item:232465|Arca de Sombrafuso} e conta cerca de 30 horas para os 25 de uma montaria.",
    [2291] = -- Salvaged Goblin Gazillionaire's Flying Machine
        "{npc:234621|Entulho do Gallagio} pode aparecer quando a barra de lixo recolhido de um evento de S.U.C.A.T.A. chega a 500, e não quando o evento termina. São precisos 3 jogadores ou mais para encher a barra. O mesmo personagem pode matá-lo várias vezes no mesmo dia; cerca de 1,6% das mortes dão a montaria.",
    [2292] = -- Miscellaneous Mechanica mounts (Innovation Investigator, Asset Advocator, Margin Manipulator)
        "{item:234741|Mecanismos Diversos} cai, raramente, dos raros que cada cartel chama em {map:2346|Inframina}, e não só na primeira morte do dia; jogadores também o acharam nas caçambas transbordando. {npc:228286|Marquita Franjínea} fica em 43.3, 82.8. Os jogadores a consideram uma das coletas mais longas da expansão: um deles comprou a terceira montaria na casa de leilões. Um jogador achou 1 ou 2 em cada {item:232465|Arca de Sombrafuso} e conta cerca de 30 horas para os 25 de uma montaria.",
    [2293] = -- Darkfuse Spy-Eye
        "{npc:231310|Precipitante de Sombrafuso} é chamado com {item:229823|Recipiente de Solução Sombrafuso}, que {npc:231396|Chico Papossério} vende a quem tem Renome 6 com {faction:2653|Cartéis da Inframina} e é Amistoso com {faction:2669|Soluções Sombrafuso}; ele vai no pilar em 40.6, 91.8 de {map:2346|Inframina}. Quem estiver ali pode saquear, uma vez por semana por personagem. Cerca de 4,3% das mortes dão a montaria.",
    [2295] = -- Undermine cartel troves (Blackwater, Steamwheedle, Venture Co., Bilgewater)
        "A arca é o que o cartel entrega cada vez que a barra de reputação enche de novo depois de Exaltado. Muitos jogadores conseguiram a montaria na primeira arca, um precisou de 16.",
    [2296] = -- Delver's mounts sold by Reno Jackson (Dirigible, Gob-Trotter, Mana-Skimmer, OC91 Chariot)
        "Apesar do que diz o diário, desde Midnight {npc:226250|Reno Jackson}, em Dornogal, a vende por 10.000 de {currency:2815|Cristais de Ressonância}.",
    [2303] = -- Violet Goblin Shredder
        "Ela vem com a recompensa de uma sequência de serviços de Fretes e Remessas em {map:2346|Inframina}, para quem tem Renome 8 com {faction:2653|Cartéis da Inframina}. Jogadores a conseguiram também fora do surto, e sem ser na primeira sequência do dia.",
    [2317] = -- Timewalking vendor mounts
        "O vendedor só está lá enquanto a Caminhada Temporal da expansão dele está ativa. {currency:1166|Insígnia Transtemporal} pode ser passada entre os personagens da conta, na aba de moedas.",
    [2322] = -- Thrayir, Eyes of the Siren
        "Thrayir está na Cripta Esquecida de {map:2369|Ilha das Sirenas} (caverna em 44.0, 23.1) entre 5 pedras rúnicas, cada uma pedindo uma chave rúnica. As chaves só são achadas e usadas na tempestade: {npc:227815|Suzi Fresaprego} (69.0, 49.1) leva você para ela depois de feita a {quest:84850|Ira da serpente} da semana.\n- {item:232571|Chave Rúnica Rodopiante}: {npc:231368|Ksvir, o Esquecido}, na cripta.\n- {item:232569|Chave Rúnica Ciclônica}: {npc:231357|Zek'ul Quebra-barco}, ou pescada onde ele aparece.\n- {item:232572|Chave Rúnica Torrencial}: 7 de {item:234328|Fragmento Torrencial}, de qualquer criatura na tempestade.\n- {item:232573|Chave Rúnica Trovejante}: 5 de {item:232605|Fragmento Trovejante}, de baús.\n- {item:232570|Chave Rúnica Turbulenta}: 3 de {item:234327|Fragmento Turbulento}, em 38.2, 51.8 · 67.1, 78.4 · 52.4, 38.6.\nUse cada chave quando a conseguir: o progresso fica.",
    [2334] = -- Bronze Goblin Waveshredder
        "{item:232465|Arca de Sombrafuso} é o que {faction:2669|Soluções Sombrafuso} entrega cada vez que a barra de reputação enche de novo depois de Exaltado. Cerca de 19% das arcas trazem a montaria.",
    [2470] = -- Timewalking vendor mounts
        "O vendedor só está lá enquanto a Caminhada Temporal da expansão dele está ativa. {currency:1166|Insígnia Transtemporal} pode ser passada entre os personagens da conta, na aba de moedas.",
    [2471] = -- Timewalking vendor mounts
        "O vendedor só está lá enquanto a Caminhada Temporal da expansão dele está ativa. {currency:1166|Insígnia Transtemporal} pode ser passada entre os personagens da conta, na aba de moedas.",
    [2473] = -- Timewalking vendor mounts
        "O vendedor só está lá enquanto a Caminhada Temporal da expansão dele está ativa. {currency:1166|Insígnia Transtemporal} pode ser passada entre os personagens da conta, na aba de moedas.",
    [2474] = -- Timewalking vendor mounts
        "O vendedor só está lá enquanto a Caminhada Temporal da expansão dele está ativa. {currency:1166|Insígnia Transtemporal} pode ser passada entre os personagens da conta, na aba de moedas.",
    [2496] = -- Void-Scarred Gryphon
        "Em {map:2404|Visão de Ventobravo}, uma das Visões Horrendas, com pelo menos 2 máscaras. Dois bilhetes rasgados no Distrito Comercial dizem o que o grifo come: o de 65.6, 71.6 diz se é cru ou cozido, o de 68.7, 73.3 diz qual comida. Ponha-a na tigela em 67.8, 73.3 e sacuda a tigela: o grifo que pousa deixa cair a montaria. A comida errada traz ratos e custa a tentativa, por isso os jogadores levam as 8. Cruas: {item:222741|Filé Fresco}, {item:222737|Micoflorescência em Pedaços}, {item:222739|Caldo de Carne Temperado}, {item:222738|Bife Porcionado}. Cozidas: {item:222702|Espetinho de Filé}, {item:222705|Micoflorescência Assada}, {item:222703|Ensopadinho}, {item:222704|Bife do Campo Sem Tempero}. Não é preciso concluir o distrito. Só um jogador do grupo recebe a montaria a cada morte.",
    [2497] = -- Void-Forged Stallion
        "Em {map:2404|Visão de Ventobravo}, uma das Visões Horrendas, com pelo menos 1 máscara, pegue as 4 ferraduras, uma por distrito: 56.1, 55.5 · 75.6, 56.8 · 61.5, 75.6 · 51.0, 84.1. Leve-as à forja em 62.9, 37.1, no Distrito dos Anões: o garanhão que aparece deixa cair a montaria. Saqueie-o, pois ela não vem pelo correio. Só funciona na semana em que a visão é a de Ventobravo. Só um jogador do grupo recebe a montaria a cada morte.",
    [2498] = -- Void-Scarred Pack Mother
        "Em {map:2403|Visão de Orgrimmar}, uma das Visões Horrendas, com pelo menos 1 máscara: pegue a sela de lobo em 67.4, 36.2 e a bolsa de arreios de lobo em 39.2, 49.6, depois clique no tapete de pele de lobo em 60.9, 55.1, dentro da loja de couraria. O lobo que aparece deixa cair a montaria. Só um jogador do grupo recebe a montaria a cada morte.",
    [2499] = -- Void-Scarred Windrider
        "Em {map:2403|Visão de Orgrimmar}, uma das Visões Horrendas, com pelo menos 2 máscaras: conclua o Vale da Sabedoria, o que libera o elevador em 49.2, 50.7. Suba e vá para o sul, até onde ficam as mantícoras (48.7, 54.9), e mate as ondas até vir a matriarca: ela deixa cair a montaria. Só um jogador do grupo recebe a montaria a cada morte.",
    [2502] = -- Void-Crystal Panther
        "Aquilo de que ela é feita só vem das Visões Horrendas, com pelo menos 1 máscara, e não é preciso profissão para juntar. Mate {npc:241024|Grande Keech} uma vez, no Vale da Honra da visão de Orgrimmar: ele dá {item:238924|Orbe do Mistério Atado ao Caos} e, a um joalheiro, a receita. Daí em diante o altar do Vale da Sabedoria dá {item:239107|Barra Infusa de Sangue Negro} e cada baú de recompensa de uma tentativa dá um {item:239106|Ônix Infuso em Sombra}. Os jogadores contam 5 tentativas. Quem não é joalheiro manda fazer por encomenda de criação.",
    [2505] = -- Resplendent K'arroc
        "Não é missão mundial, apesar do que diz o diário: {npc:231820|Ve'nari}, no Oásis de {map:2371|K'aresh}, oferece {quest:88976|A esperança de K'aresh} a quem tem {achievement:41811|Estabilidade ecológica}.",
    [2511] = -- Terror of the Night
        "Os mandados são semanais: a cada semana vem um de 6, sorteado, em 48.7, 57.7 de {map:2472|Tazavesh, o Mercado Oculto}, e cada um é uma cadeia curta que termina com um raro para chamar e matar. Com os 6 feitos vem a montaria: seis semanas no mínimo.",
    [2512] = -- Delver's mounts sold by Reno Jackson (Dirigible, Gob-Trotter, Mana-Skimmer, OC91 Chariot)
        "Apesar do que diz o diário, desde Midnight {npc:226250|Reno Jackson}, em Dornogal, a vende por 10.000 de {currency:2815|Cristais de Ressonância}.",
    [2535] = -- Void-Scarred Lynx
        "Ela vem na {item:239546|Bolsa do Sectário Confiscada}, a bolsa das missões DIÁRIAS das incursões em {map:2215|Pouso Santo}, e não na algibeira semanal. Cerca de 0,7% das bolsas a trazem; os relatos vão da 3ª bolsa a mais de 500.",
    [2552] = -- Lavender K'arroc, Acidic Void Creeper (Untethered Coin)
        "{quest:91093|Não é só uma fase} dá 7 de {currency:3303|Moeda Desprendida} por semana à conta inteira. {npc:241624|Shad'anis} pede 66 por tudo o que vende.",
    [2557] = -- Lavender K'arroc, Acidic Void Creeper (Untethered Coin)
        "{quest:91093|Não é só uma fase} dá 7 de {currency:3303|Moeda Desprendida} por semana à conta inteira. {npc:241624|Shad'anis} pede 66 por tudo o que vende.",
    [2560] = -- Blue Barry
        "No Renome 9 com {faction:2658|Truste K'areshi}, {npc:238016|Ba'eth} (57.6, 58.1 em {map:2472|Tazavesh, o Mercado Oculto}) começa uma cadeia que anda um passo por dia, de {quest:90663|Roubar o que é nosso} até {quest:90769|Tudo azul}, que dá a montaria. Quatro dias no mínimo, e um dia sem fazer é um dia a mais.",
    [2561] = -- Curious Slateback
        "{item:245611|Depósito Pináculo Estrebuchante} vem uma vez por semana, e cerca de 3 depósitos em 100 trazem a montaria. Jogadores o abriram toda semana por meses.",
    [2586] = -- Timewalking vendor mounts
        "O vendedor só está lá enquanto a Caminhada Temporal da expansão dele está ativa. {currency:1166|Insígnia Transtemporal} pode ser passada entre os personagens da conta, na aba de moedas.",
    [2587] = -- Timewalking vendor mounts
        "O vendedor só está lá enquanto a Caminhada Temporal da expansão dele está ativa. {currency:1166|Insígnia Transtemporal} pode ser passada entre os personagens da conta, na aba de moedas.",
    [2601] = -- Pearlescent Krolusk
        "Você precisa estar em Mergulho Fásico para ver e atacar {npc:232195|Urmag}. Ele volta a cada 10 a 20 minutos, e o saque é uma vez por dia por personagem, então personagens alternativos ajudam. Quando ele não puder ser atacado, está sob o véu do chefe mundial ao lado: puxe-o para longe do chefe, ou para trás do pedaço de domo ao lado de onde ele aparece, até o efeito sumir.",
    [2602] = -- Translocated Gorger
        "Ela é feita de 20 de {item:246240|Cápsula de Energia Devorada}. Cada um dos 4 raros dos ataques de devoradores dá uma por semana à conta: {npc:231229|Korgoth, o Voraz} (71.8, 28.2), {npc:234970|Iramiasma} (50.6, 54.0) e um terceiro em 49.5, 64.2 em {map:2371|K'aresh}, {npc:235104|O Quebramuros} (28.6, 74.3) em {map:2472|Tazavesh, o Mercado Oculto}. São 4 por semana no máximo, portanto 5 semanas. Um ataque acontece de cada vez, e o mapa o mostra; o raro vem quando a barra de devoradores mortos enche.",
    [2603] = -- Sthaarbs's Last Lunch
        "{npc:234845|Sthaarbs} aparece no meio do Oásis de {map:2371|K'aresh} (74.0, 32.5) cerca de uma hora depois de morrer, e só pode ser enfrentado de dentro do Mergulho Fásico: é preciso ter {item:235499|Faixas de Reshii} e nível 80. Ao lado do conduíte em 75.8, 33.0 um botão extra leva você às plataformas em volta dele. Saque uma vez por semana por personagem; cerca de 6,8% das mortes dão a montaria.",
    [2604] = -- Delver's mounts sold by Reno Jackson (Dirigible, Gob-Trotter, Mana-Skimmer, OC91 Chariot)
        "Apesar do que diz o diário, desde Midnight {npc:226250|Reno Jackson}, em Dornogal, a vende por 10.000 de {currency:2815|Cristais de Ressonância}.",
    [2605] = -- Inarius' Charger
        "Só durante o evento Um Emissário Ganancioso (julho de 2025). {npc:205490|Goblins do Tesouro} saíam de portais em Ventobravo, Orgrimmar e Dornogal, e em {map:2346|Inframina} depois da morte de raros, onde grupos de raide os caçavam. Não há bloqueio: o mesmo personagem pode saquear um goblin atrás do outro. Se ela cair em grupo, pode ser negociada com os jogadores desse grupo.",
    [2615] = -- Rootstalker Grimlynx, Vibrant Petalwing (Harandar rares)
        "Qualquer raro de {map:2413|Harandar} pode deixá-la cair, cada um com cerca de 0,1% de chance. Um raro dá saque uma vez por dia por personagem, por isso os jogadores repetem a volta em outros personagens, inclusive de nível 80. Os relatos vão da primeira morte a mais de 2.000.",
    [2655] = -- Phase-Lost Slateback
        "Os orbes de {achievement:61017|Achados e perdidos na fase} só aparecem dentro do Mergulho Fásico, em {map:2371|K'aresh} e em Tazavesh, e pedem {item:235499|Faixas de Reshii} no grau 3. Cerca de 20% dos orbes dão uma arma, sempre uma que você ainda não tem. Dois jogadores não pegam o mesmo orbe. Os jogadores fizeram em 30 minutos a algumas horas, dando a volta nas ilhas.",
    [2693] = -- Blessed Amani Burrower, Amani Sunfeather (Abundance vendor)
        "O diário diz 1.600 de {currency:3377|Abundância Impoluta}, mas {npc:241928|Chel, a Estilha} cobra 6.400.",
    [2708] = -- Rootstalker Grimlynx, Vibrant Petalwing (Harandar rares)
        "Qualquer raro de {map:2413|Harandar} pode deixá-la cair, cada um com cerca de 0,1% de chance. Um raro dá saque uma vez por dia por personagem, por isso os jogadores repetem a volta em outros personagens, inclusive de nível 80. Os relatos vão da primeira morte a mais de 2.000.",
    [2713] = -- Ruddy Sporeglider
        "O Caldeirão Peculiar (40.7, 28.1 em {map:2413|Harandar}) abre com 150 de {item:260531|Fragmento de Resina Cristalizada}. Eles vêm, de 2 a 7 por vez, da Seiva Endurecida pelo Fogo de Teldrassil caída no rio que corre de 40.0, 21.4 até 49.3, 51.2, e em nenhuma outra água. A seiva volta tão depressa quanto é recolhida. Do alto, sobre o rio, o contorno dela é mais fácil de ver.",
    [2747] = -- Untainted Grove Crawler
        "Em {map:2413|Harandar}: toque na Marreta Fúngica em 41.3, 67.9, que dá um efeito de 5 minutos, e com o efeito ativo toque o Gongo de Micélio em 46.6, 67.8. O Baú Gera-esporos aparece ao lado do gongo. Um jogador só viu o gongo depois de matar as criaturas em volta; outro clicou no baú, não recebeu nada, e a montaria chegou pelo correio horas depois.",
    [2749] = -- Echo of Aln'sharan
        "1. Faça a cadeia curta de {npc:245637|Su'meera} que começa em {quest:91063|A Trama Florescente} (65.4, 22.6 em {map:2413|Harandar}) e depois a de {npc:242358|Kuri} (67.8, 24.8), de {quest:90467|Contos do céu} até {quest:90474|A lenda de Aln'sharan}. Basta um personagem da conta.\n2. Daí em diante as criaturas de Harandar deixam cair {item:255826|Estilhaços do Céu Misteriosos}, também em imersões e masmorras; os raros, com muito mais frequência. Junte 500.\n3. Entregue-os a Kuri em 66.2, 25.5 pelo botão de ação extra. Parece que nada acontece, mas você recebe um efeito.\n4. Aln'sharan voa alto sobre a zona e fere quem chega perto. Desmonte no ar junto à cabeça dele e clique nele, com uma queda lenta à mão.\nJogadores perderam o efeito, e os 500 estilhaços com ele, ao entrar em grupo ou em campo de batalha antes do passo 4.",
    [2751] = -- Augmented Stormray, Sanguine Harrower (Voidstorm rares)
        "Qualquer raro de {map:2405|Tempestade do Caos} pode deixá-la cair, cada um com cerca de 0,1% de chance. Um raro dá saque uma vez por dia por personagem, por isso os jogadores repetem a volta em outros personagens, inclusive de nível 80. Os relatos vão da primeira morte a mais de 2.000.",
    [2758] = -- Cobalt Dragonhawk, Cerulean Hawkstrider (Eversong Woods rares)
        "Qualquer raro de {map:2395|Floresta do Canto Eterno} pode deixá-la cair, cada um com cerca de 0,1% de chance. Um raro dá saque uma vez por dia por personagem, por isso os jogadores repetem a volta em outros personagens. Os relatos vão da primeira morte a mais de 2.000.",
    [2760] = -- Amani Sharptalon, Witherbark Pango (Zul'Aman rares)
        "Qualquer raro de {map:2437|Zul'Aman} pode deixá-la cair, cada um com cerca de 0,1% de chance. Um raro dá saque uma vez por dia por personagem, por isso os jogadores repetem a volta em outros personagens. Os relatos vão de poucas mortes a mais de 2.000.",
    [2762] = -- Cobalt Dragonhawk, Cerulean Hawkstrider (Eversong Woods rares)
        "Qualquer raro de {map:2395|Floresta do Canto Eterno} pode deixá-la cair, cada um com cerca de 0,1% de chance. Um raro dá saque uma vez por dia por personagem, por isso os jogadores repetem a volta em outros personagens. Os relatos vão da primeira morte a mais de 2.000.",
    [2764] = -- Duskbrute Harrower
        "{item:267299|Tesouro do Duellum do Matador} é o que {faction:2770|Duellum do Matador} entrega cada vez que a barra de reputação enche de novo depois de a reputação chegar ao máximo. Cerca de 26% dos tesouros trazem a montaria; os outros podem trazer a mesma mascote repetidas vezes.",
    [2767] = -- Contained Stormarion Defender
        "Dois depósitos podem trazê-la, poucos em cada cem: {item:268485|Depósito Pináculo de Tempestrião Vitorioso}, o semanal por concluir {quest:90962|Assalto a Tempestrião}, e {item:260979|Depósito de Tempestrião Vitorioso}, o da missão mundial do evento. A missão mundial só aparece para o personagem que já concluiu o evento uma vez.",
    [2772] = -- Blessed Amani Burrower, Amani Sunfeather (Abundance vendor)
        "O diário diz 1.600 de {currency:3377|Abundância Impoluta}, mas {npc:241928|Chel, a Estilha} cobra 6.400.",
    [2775] = -- Amani Sharptalon, Witherbark Pango (Zul'Aman rares)
        "Qualquer raro de {map:2437|Zul'Aman} pode deixá-la cair, cada um com cerca de 0,1% de chance. Um raro dá saque uma vez por dia por personagem, por isso os jogadores repetem a volta em outros personagens. Os relatos vão de poucas mortes a mais de 2.000.",
    [2778] = -- Ancestral War Bear
        "O Baú do Guerreiro Honrado fica dentro da base da árvore em 47.0, 82.4 de {map:2437|Zul'Aman}. Clique nele primeiro: só então as quatro Urnas do Guerreiro Honrado respondem. Cada urna chama um guardião que deixa um símbolo: {npc:255171|Escolhido de Nalorakk} em 32.6, 83.5, {npc:255232|Escolhido de Halazzi} em 34.5, 33.4, {npc:255233|Escolhido de Jan'alai} em 54.7, 22.3 e {npc:255231|Escolhido de Akil'zon} em 51.5, 84.9. Com os quatro símbolos, volte ao baú.",
    [2779] = -- Witherbark Warbear Mother
        "Leve 6 de {item:242639|Carne Mais ou Menos Suína} (casa de leilões, ou as feras do lado de fora) para o Sítio Ritualístico {map:2585|Trono Partido}, em Grau 2 ou maior. O Ursinho Perdido fica escondido ao lado de uma árvore em 55.8, 49.5, num patamar a que se chega pulando de cima: dê 1 a ele e ele vira a mascote {item:269836|Gorducho}. Evoque Gorducho junto à Carne Mastigada em 56.0, 38.5 e vem uma ursa de guerra raivosa. Vença-a; ela fica amistosa, e você dá a ela as outras 5.",
    [2786] = -- Hexed Vilefeather Eagle
        "A Caveira de Ritual Abandonada fica numa caverna pequena de {map:2437|Zul'Aman}, em 44.7, 44.1 (entrada em 44.2, 43.5), e pede 1.000 de {item:259361|Essência Torpe}, deixada pelas criaturas da área de elites em volta de 45.8, 40.2. Os jogadores contam de 6 a 7 horas.\nO que torna isso suportável: pegue ali {quest:91838|Vileza enfraquecida}, {quest:91836|Respeite o totem} e {quest:91835|Mandando para casa} e NÃO as entregue. Enquanto elas estão no registro você mantém um botão de ação extra com um efeito, e cada {npc:248775|Guardião Selvagem} morto dá um segundo. Desde abril de 2026 cada um acumula só 3 vezes, e não 10, e dura 3 minutos: ajuda menos, e sozinho é mais difícil do que dizem os relatos antigos. Desligue addon que entrega missão por conta própria. Quem já fez essas missões faz em outro personagem.",
    [2790] = -- Insatiable Shredclaw
        "A caverna fica no sul de {map:2405|Tempestade do Caos}, com entrada em 48.9, 78.4. Dentro, ovos quebrados formam um labirinto de círculos de raios; ser atingido devolve você à entrada. A Garra Final de Predaxas está no fim. Jogadores dizem que o círculo para de ferir um pouco antes de sumir, e que um rastro de vento no chão mostra o caminho.",
    [2827] = -- Augmented Stormray, Sanguine Harrower (Voidstorm rares)
        "Qualquer raro de {map:2405|Tempestade do Caos} pode deixá-la cair, cada um com cerca de 0,1% de chance. Um raro dá saque uma vez por dia por personagem, por isso os jogadores repetem a volta em outros personagens, inclusive de nível 80. Os relatos vão da primeira morte a mais de 2.000.",
    [2829] = -- Lab-Grown Stormray
        "{achievement:62385|De olho no caos} pede 7 de {currency:3400|Amostra do Caos Imaculada}: 1 no começo, depois a cada semana 1 da missão semanal de {npc:248328|Pesquisador do Caos Anomandra}, ao lado do console, e 1 do depósito semanal de {quest:90962|Assalto a Tempestrião}. Cerca de 3 semanas. Se a montaria não vier com a conquista, olhe o correio, ou use Asas do Caos no grimório: a magia põe o item na sua bolsa, onde quer que você esteja.",
    [2839] = -- Delver's Arcane Golem
        "Dentro da imersão Ilha Dendronor, em qualquer Grau: o Baú Resistente em 60.4, 68.1. A imersão tem três Baús Resistentes; a montaria veio deste.",
    [2913] = -- Vivid Chloroceros, Elder Glowmite (Luminous Dust)
        "{currency:3385|Poeira Luminosa} vem das Mariposas Brilhantes espalhadas por {map:2413|Harandar}, 120 ao todo. Elas se abrem em três grupos de 40, nos Renomes 1, 5 e 6 com {faction:2704|Hara'ti}; o mapa só marca cada grupo depois, nos Renomes 2, 6 e 11. O jogador que as mapeou aconselha chegar ao Renome 9 antes de sair à procura.",
    [2950] = -- Luminous Sporeglider
        "Ela é feita combinando 4 de {item:269245|Lanchesporo Delicioso}. {npc:254176|Necrocharco} dá um por semana para a conta inteira, em qualquer dificuldade: quatro semanas no mínimo.",
    [2961] = -- Void-Corrupted Hex Eagle
        "No Sítio Ritualístico {map:2585|Trono Partido}, em Grau 2 ou maior. Uma das quatro caveiras em volta do círculo de ritual em 50.6, 47.3 está sem vela: pegue a Vela Ritualística Fora do Lugar debaixo da árvore em 51.5, 47.8 e coloque-a na caveira a nordeste do círculo. Depois clique nas velas do meio e mate a águia que vem: ela deixa cair a montaria. Se vierem três filhotes de águia, a vela não estava no lugar.",
    [2964] = -- Void-Touched Snapdragon
        "No Sítio Ritualístico {map:2594|Ponto de Espinhadaga}, em qualquer Grau, aparecem até 2 Algas Trazidas pela Água por entrada, entre 8 pontos ao longo das praias. Clicar numa chama criaturas e, com uma chance pequena, o Dracolisco Tocado pelo Caos, que deixa cair a montaria. Os jogadores conferem as algas, saem da instância e entram de novo, sem fazer o ritual. Os {item:228966|Óculos de Visão de Estrelas} deixam as algas mais fáceis de ver. Os relatos vão de 25 tentativas a cerca de 70 algas clicadas.",
    [2965] = -- Void-Corrupted Lynx
        "Esta montaria é fabricada, não saqueada. O {item:270058|Arnês do Lince de Corda} é feito com Couraria de Midnight (90) a partir de 1 {item:272392|Coleira de Lince Danificada}, 40 de {item:236950|Grânulo de Energia Primeva}, 1 {item:244634|Pelego Tecido em Escamas Imbuído} e 2 de {item:244636|Elo de Armadura Sin'dorei}.\nA coleira é a parte que se saqueia: a arca ritualística no fim de um Sítio Ritualístico a dá em 1,5% das aberturas no {map:2585|Trono Partido} e 0,5% no {map:2594|Ponto de Espinhadaga}, em qualquer Grau. Os jogadores só a relatam depois do Renome 8 com os {faction:2792|Sítios Ritualísticos}. Ela se vincula a você.\nO {item:272391|Molde: Arnês do Lince de Corda} sai da mesma arca no Trono Partido (0,3%) e pode ser comprado na casa de leilões. Sem Couraria, envie a coleira num pedido de criação a um coureiro que tenha o molde.",
    [2980] = -- Spirit of Tok'jara
        "No Renome 10 com {faction:2772|Forças de Zul'jarra}, {npc:264611|Du'gal} (50.5, 63.9 em {map:2509|Câmaras de Atal'Utek}) começa uma cadeia de 6 missões, uma por dia, de {quest:96267|Gemas ancestrais} até {quest:96305|A essência inocente}, que dá a montaria. Seis dias no mínimo, e a cadeia é do personagem que a começou.",
    [3005] = -- Lindormi's six mounts (Timelost Saddle)
        "Na 1ª temporada de Midnight, a {item:275436|Sela Perdida no Tempo} veio com {achievement:63097|Mito da Pedra-chave de Midnight: Série 1}, 3.400 de pontuação de Mítica+, e expirou quando a temporada acabou. Cada sela comprava uma das montarias que {npc:197711|Lindormi} vende, à escolha do jogador.",
    [3006] = -- Lindormi's six mounts (Timelost Saddle)
        "Na 1ª temporada de Midnight, a {item:275436|Sela Perdida no Tempo} veio com {achievement:63097|Mito da Pedra-chave de Midnight: Série 1}, 3.400 de pontuação de Mítica+, e expirou quando a temporada acabou. Cada sela comprava uma das montarias que {npc:197711|Lindormi} vende, à escolha do jogador.",
    [3007] = -- Lindormi's six mounts (Timelost Saddle)
        "Na 1ª temporada de Midnight, a {item:275436|Sela Perdida no Tempo} veio com {achievement:63097|Mito da Pedra-chave de Midnight: Série 1}, 3.400 de pontuação de Mítica+, e expirou quando a temporada acabou. Cada sela comprava uma das montarias que {npc:197711|Lindormi} vende, à escolha do jogador.",
    [3008] = -- Lindormi's six mounts (Timelost Saddle)
        "Na 1ª temporada de Midnight, a {item:275436|Sela Perdida no Tempo} veio com {achievement:63097|Mito da Pedra-chave de Midnight: Série 1}, 3.400 de pontuação de Mítica+, e expirou quando a temporada acabou. Cada sela comprava uma das montarias que {npc:197711|Lindormi} vende, à escolha do jogador.",
    [3009] = -- Lindormi's six mounts (Timelost Saddle)
        "Na 1ª temporada de Midnight, a {item:275436|Sela Perdida no Tempo} veio com {achievement:63097|Mito da Pedra-chave de Midnight: Série 1}, 3.400 de pontuação de Mítica+, e expirou quando a temporada acabou. Cada sela comprava uma das montarias que {npc:197711|Lindormi} vende, à escolha do jogador.",
    [3010] = -- Lindormi's six mounts (Timelost Saddle)
        "Na 1ª temporada de Midnight, a {item:275436|Sela Perdida no Tempo} veio com {achievement:63097|Mito da Pedra-chave de Midnight: Série 1}, 3.400 de pontuação de Mítica+, e expirou quando a temporada acabou. Cada sela comprava uma das montarias que {npc:197711|Lindormi} vende, à escolha do jogador.",
    [3029] = -- Apophic Soul Crusher
        "{npc:265500|Azta'rec} é o nêmesis das imersões da 2ª temporada, na imersão dele, Profundezas de Peçonheira (51.2, 30.4 em {map:2512|A Ilha Enrolada}). A montaria é de {achievement:63333|Me deixa solar: Azta'rec}: derrote-o no grau ?? sem nenhum outro jogador no grupo. Ela chega pelo correio. A conquista diz \"durante a 2ª temporada de Midnight\". {achievement:63326|Minha nêmesis peçonhenta}, de qualquer um dos dois graus, dá {item:276163|Patágios Apóficos}, que é uma aparência e não uma montaria.",
    [3031] = -- Hexflame Reaver
        "{npc:258928|Ral'kala} é chamado queimando {item:274422|Relíquia Ossificada} num {npc:265151|Braseiro Assombrado} de {map:2512|A Ilha Enrolada}, 100 para cada chamada, com o modo Pesadelo das caçadas ligado. Para ter saque é preciso ter posto pelo menos 1 relíquia você mesmo e ter acertado nele: o efeito Sussurros do Outro Lado mostra que a sua relíquia contou. Ele não tem limite diário, por isso os grupos o chamam de novo e de novo. A caçada diária no norte da ilha dá 100 relíquias. Enquanto espera, não mate as criaturas em volta do braseiro: isso traz cobras sobre o grupo inteiro.",
    [3036] = -- Sun Festival's Painted Roc
        "Ela vem na {item:117394|Algibeira de Itens Gelados}, entregue pelo primeiro {npc:25740|Ahune} do dia. Só a primeira algibeira do dia da conta inteira pode trazer a montaria. Desde um ajuste de junho de 2026 essa chance dobrou, e ela cresce a cada dia até a montaria vir.",
    [3043] = -- Corroded Soul Crusher
        "O item só diz que a Jornada do Imersor a desbloqueia. Jogadores relatam o grau 5 da Jornada da 2ª temporada.",
    [3051] = -- Topaz Skyfang, Ruby Writhe (Coiled Isle rares)
        "Qualquer raro de {map:2512|A Ilha Enrolada} pode deixá-la cair, cada um com cerca de 0,1% de chance. Um raro dá saque uma vez por dia por personagem, por isso os jogadores repetem a volta em outros personagens. Os relatos vão da primeira morte a mais de 1.200.",
    [3061] = -- Topaz Skyfang, Ruby Writhe (Coiled Isle rares)
        "Qualquer raro de {map:2512|A Ilha Enrolada} pode deixá-la cair, cada um com cerca de 0,1% de chance. Um raro dá saque uma vez por dia por personagem, por isso os jogadores repetem a volta em outros personagens. Os relatos vão da primeira morte a mais de 1.200.",
}

-- What is of each mount (`own`), by mount id.
ns.MountTipsOwnLocal = {
    [286] = "Cai muito raramente de Armagedom, e também do Arcavon do aniversário, em Tanaris (2024, 2025). Em qualquer época do ano: qualquer um dos quatro chefes da Abóbada de Arcavon, em {map:123|Invérnia}, uma vez por semana por personagem. A versão da Aliança e a da Horda valem para as duas facções.",
    [287] = "Cai muito raramente de Armagedom, e também do Arcavon do aniversário, em Tanaris (2024, 2025). Em qualquer época do ano: qualquer um dos quatro chefes da Abóbada de Arcavon, em {map:123|Invérnia}, uma vez por semana por personagem. A versão da Aliança e a da Horda valem para as duas facções.",
    [293] = "Desde 2024 ela não cai mais com certeza. No evento de 2024, {npc:158061|Historiadora Ma'di} também a vendia por 5.000 {currency:1166|Insígnias Transtemporais}.",
    [534] = "Só cai do Armipotente montado num escornante de âmbar.",
    [535] = "Só cai do Armipotente montado num escornante de ardósia.",
    [536] = "Só cai do Armipotente montado num escornante de jade.",
    [803] = "Só para personagem Venthyr. {npc:179985|Esmaga-pedras Estígio} deixa cair um cristal, um item que começa uma missão: a missão dá a montaria.",
    [955] = "{npc:127288|Mestre de Matilha Kerrax} fica dentro de uma caverna; a entrada é em 63.1, 25.2 nos {map:885|Ermos Antoranos}.",
    [981] = "Dois raros a deixam cair, {npc:126040|Puscilla} e {npc:126199|Vrax'thul}, cada um com o seu próprio saque diário.",
    [1173] = "Só para a Horda: {npc:142739|Capitão-cavaleiro Alderico} é um capitão da Aliança, e só jogadores da Horda podem atacá-lo.",
    [1174] = "Só para a Aliança: {npc:142741|Cavaleiro da Perdição Helgueiro} é um cavaleiro da Horda, e só jogadores da Aliança podem atacá-lo. Ele volta poucos minutos depois de morrer, mas só a primeira morte do ciclo pode dar saque.",
    [1182] = "{npc:142423|Feitor Krix} fica dentro de uma mina: a de 33.0, 37.5 enquanto a Aliança controla a zona, e a de 27.5, 55.9 enquanto a Horda controla.",
    [1199] = "Jogadores da Aliança matam {npc:149652|Ágata Bosque da Serpe}; jogadores da Horda matam o urso no mesmo lugar.",
    [1200] = "{npc:148787|Alash'anir} está lá para as duas facções, qualquer que seja a que controla a zona.",
    [1203] = "Jogadores da Aliança matam {npc:147701|Moxo, o Decapitador}; jogadores da Horda matam {npc:148037|Athil Fogorvalha}.",
    [1205] = "Jogadores da Aliança matam {npc:149655|Croz Fúria Sanguinária}; jogadores da Horda matam {npc:149663|Garrassombra}.",
    [1229] = "O {npc:154342|Ceifador Aracnídeo} do futuro alternativo da ilha também a deixa cair. Chega-se lá com a missão diária de {npc:153993|Crona}, {quest:55816|O outro lugar}, nos dias em que ela visita a ilha, ou com o {item:169114|Deslocador Pessoal de Tempo}.",
    [1311] = "Pegue a serpente com um {item:174927|Laço Zan-Tien}, que cai dos mogus Zan-Tien do Vale. Ela aparece no alto sobre 26.8, 55.1, mais ou menos no topo do grande portão a oeste, logo abaixo do {npc:152550|Grande Verme do Além}, e sai voando rápido. O laço leva 2 segundos, parado; depois da primeira captura ela fica alguns segundos, e outros também podem pegá-la.",
    [1314] = "{npc:157134|Ishak dos Quatro Ventos} aparece em qualquer ataque que Uldum tenha, com 2 a 4 horas entre uma vez e outra. Ele surge fora da torre e voa até a plataforma flutuante em volta da qual circula: espere por ele ali.",
    [1317] = "{npc:157146|Putrífago} só está lá enquanto o ataque a Uldum é {quest:55350|Ataque: avanço Amatet}, por alguns dias mais ou menos a cada duas semanas. Ele volta de 40 a 90 minutos depois de morrer, cerca de uma hora em média.",
    [1319] = "{npc:162147|Comedor de Cadáveres} só está lá enquanto o ataque a Uldum é {quest:56308|Ataque: os aqir desenterrados}. Ele volta de 3 a 20 minutos depois de morrer. A Blizzard aumentou a chance em março de 2020, sem dizer quanto.",
    [1355] = "A maioria dos jogadores que a têm a conseguiu com um {item:177699|Espírito Indomado Superior} e 2 farinhas, um deles com o conservatório ainda no nível 2.",
    [1358] = "Os jogadores a conseguiram com 4 farinhas em volta da semente, de um {item:177699|Espírito Indomado Superior}, um {item:177700|Espírito Indomado Divino} ou um {item:183704|Espírito Cambiante do Conhecimento}.",
    [1392] = "Kyrianos: compre de {npc:171973|Binkiros} por 2.500 de {currency:1813|Ânima-reserva} depois da conquista {achievement:14860|Só o necessário}, do Caminho da Ascensão. Feérios Noturnos: {item:177700|Espírito Indomado Divino}. Venthyr: tributo da Capitã de Caça Korayn.",
    [1408] = "Kyrianos: compre de {npc:171973|Binkiros} por 2.500 de {currency:1813|Ânima-reserva} depois da conquista {achievement:14853|Sommelier de sofrimento}, do Caminho da Ascensão. Feérios Noturnos: {item:178878|Espírito Marcial Divino}. Venthyr: tributo de Alexandros Mograine; dois jogadores a conseguiram na primeira vez em que o convidaram.",
    [1413] = "Kyrianos: é a recompensa por derrotar {npc:172333|Azaruux} numa Prova da Sabedoria do Caminho da Ascensão; Binkiros não a vende. Feérios Noturnos: {item:178879|Espírito Obediente Divino}. Venthyr: tributo de Mikâniko.",
    [1449] = "Só para personagem dos Necrolordes. {npc:180042|Carnala} deixa cair um ovo, que choca depois de 3 dias. O ovo vem sem mensagem nenhuma: olhe a bolsa.",
    [1487] = "Só para personagem dos Feérios Noturnos. {npc:180013|Silvestrito Fugido} deixa cair uma sela, um item que começa uma missão: a missão dá a montaria.",
    [1493] = "Só para personagem dos Kyrianos. {npc:180032|Quebra-mundo Selvagem} deixa cair um núcleo, um item que começa uma missão: a missão dá a montaria.",
    [1798] = "Desde 2024 ela não cai mais com certeza. No evento de 2024, {npc:158061|Historiadora Ma'di} também a vendia por 5.000 {currency:1166|Insígnias Transtemporais}.",
    [1808] = "Só com uma {item:208047|Semente do Sonho Gigante} (roxa) sua: a {item:208067|Semente do Sonho Roliça} (azul) e a {item:208066|Semente do Sonho Pequena} (verde) nunca a dão. Cerca de 0,5% por baú, e 2,8% para alguma das seis desta semente. O jogo não diz que a barra conta para ela. {npc:212797|Talisa Cantaflora} também a vende, por 1 {item:211376|Flor-de-gérmen} da missão semanal dela, com renome 18 com {faction:2574|Guardiões do Sonho}.",
    [1810] = "Só com uma {item:208047|Semente do Sonho Gigante} (roxa) sua: a {item:208067|Semente do Sonho Roliça} (azul) e a {item:208066|Semente do Sonho Pequena} (verde) nunca a dão. Cerca de 0,5% por baú, e 2,8% para alguma das seis desta semente. O jogo não diz que a barra conta para ela. {npc:212797|Talisa Cantaflora} também a vende, por 1 {item:211376|Flor-de-gérmen} da missão semanal dela, com renome 18 com {faction:2574|Guardiões do Sonho}.",
    [1815] = "Com qualquer semente sua, ou só orvalho na planta de alguém. Cerca de 0,5% por baú. O jogo diz que a chance cresce quando a barra da planta chega a 50 e de novo em 100, e não diz quanto. Não é vendida.",
    [1816] = "Só com uma {item:208047|Semente do Sonho Gigante} (roxa) sua: a {item:208067|Semente do Sonho Roliça} (azul) e a {item:208066|Semente do Sonho Pequena} (verde) nunca a dão. Cerca de 0,5% por baú, e 2,8% para alguma das seis desta semente. O jogo não diz que a barra conta para ela. {npc:212797|Talisa Cantaflora} também a vende, por 1 {item:211376|Flor-de-gérmen} da missão semanal dela, com renome 18 com {faction:2574|Guardiões do Sonho}.",
    [1817] = "Só com uma {item:208047|Semente do Sonho Gigante} (roxa) sua: a {item:208067|Semente do Sonho Roliça} (azul) e a {item:208066|Semente do Sonho Pequena} (verde) nunca a dão. Cerca de 0,5% por baú, e 2,8% para alguma das seis desta semente. O jogo não diz que a barra conta para ela. {npc:212797|Talisa Cantaflora} também a vende, por 1 {item:211376|Flor-de-gérmen} da missão semanal dela, com renome 18 com {faction:2574|Guardiões do Sonho}.",
    [1833] = "Só com uma {item:208047|Semente do Sonho Gigante} (roxa) sua: a {item:208067|Semente do Sonho Roliça} (azul) e a {item:208066|Semente do Sonho Pequena} (verde) nunca a dão. Cerca de 0,5% por baú, e 2,8% para alguma das seis desta semente. O jogo não diz que a barra conta para ela. {npc:212797|Talisa Cantaflora} também a vende, por 1 {item:211376|Flor-de-gérmen} da missão semanal dela, com renome 18 com {faction:2574|Guardiões do Sonho}.",
